import type { DocumentContent } from "../documents";

const content = {
    html: resolveAssets("<h1 id=\"memory\">Memory</h1><p>TypeScript, like many managed high level languages, does not encode memory &quot;ownership&quot; in its type system: all reference types are implicitly GC-managed on some (local) heap, and all value types are copied by default.\nThat is convenient and often what we want, but sometimes we need to take direct control of memory, whether for better performance, or just to express certain invariants in the code.</p>\n<p>Destack supports explicit, optional type modifiers for controlling memory <em>placement</em> and <em>ownership</em>:</p>\n<ul>\n<li><strong>Placement</strong> - where the value is located: ambient by default, explicitly <code>local</code> to one Worker, <code>shared</code> across Workers (or <code>static</code> for constant and <code>frame</code> for activation frames).</li>\n<li><strong>Ownership</strong> - who &quot;owns&quot; the value: managed (<code>T</code>), owned (<code>^T</code>), borrowed (<code>&amp;T</code>, <code>&amp;readonly T</code>, <code>&amp;exclusive T</code>), or raw (<code>*T</code>).</li>\n</ul>\n<p>The two axes of ownership and placement compose and commute freely, e.g. <code>shared ^T</code> and <code>^shared T</code> both mean an owned handle to a value in shared space, and <code>shared &amp;T</code> is a borrow of a shared value.\nOnce structural shapes and constraints have been <a href=\"/docs/language/types/#representation\">reified, instantiated, or erased</a>, the plain old <code>T</code> still behaves as the type&#39;s default representation, exactly like we&#39;re used to from TypeScript: value types are values, object types are managed references, both can be aliased and mutated freely (locally).</p>\n<p>Everything in this chapter follows from four rules:</p>\n<ol>\n<li>Every value has exactly one owner - for managed values, the owner is the runtime.</li>\n<li>A borrow must remain valid: a place cannot move or drop while an overlapping borrow is live, and a borrow cannot outlive the source it came from.</li>\n<li>Exclusive borrows are truly exclusive: no overlapping borrow of the same place may be live.</li>\n<li>Shared memory must never point into local memory.</li>\n</ol>\n<h2 id=\"ownership\">Ownership</h2><p>Ownership determines who keeps a value alive, who is allowed to mutate it, and when and how it is eventually freed.\nThe notion of ownership has many names and forms, but today it is most commonly associated with Rust&#39;s explicit ownership system, and that is also the system most similar to Destack.\nReally, &quot;ownership&quot; just means that each <em>value</em> has an owner and certain rules apply to how we can pass and store values to certain places, depending on which level of mutability and ownership they need.</p>\n<p>The usual explanation of &quot;ownership&quot; sounds more complex than it is, especially to developers used to &quot;managed&quot; languages, and <em>especially</em> because Rust tradition (deliberately) unifies &quot;liveness&quot;, &quot;exclusivity&quot; and &quot;mutability&quot; while only liveness is required for memory safety.\nUnlike Rust, Destack supports <em>both</em> multiple mutable borrows (<code>&amp;T</code>) and exclusive mutable borrows (<code>&amp;exclusive T</code>):</p>\n<div class=\"markdown-table\" tabindex=\"0\"><table><thead><tr>\n<th>Form</th>\n<th>Meaning</th>\n<th>Mutable?</th>\n<th>Exclusive?</th>\n</tr>\n</thead><tbody><tr>\n<td><code>T</code></td>\n<td>default value form: direct for value types, managed for reference types</td>\n<td>yes</td>\n<td>depends on the default form</td>\n</tr>\n<tr>\n<td><code>^T</code></td>\n<td>owned value form</td>\n<td>yes</td>\n<td>yes (single owner)</td>\n</tr>\n<tr>\n<td><code>&amp;T</code></td>\n<td>borrowed access</td>\n<td>yes</td>\n<td>no</td>\n</tr>\n<tr>\n<td><code>&amp;readonly T</code></td>\n<td>readonly borrowed access</td>\n<td>no</td>\n<td>no</td>\n</tr>\n<tr>\n<td><code>&amp;exclusive T</code></td>\n<td>exclusive borrowed access</td>\n<td>yes</td>\n<td>yes</td>\n</tr>\n<tr>\n<td><code>*T</code></td>\n<td>raw pointer</td>\n<td>yes (unchecked)</td>\n<td>no (unchecked)</td>\n</tr>\n</tbody></table></div><p>The owner of a value is responsible for keeping it alive, and also for disposing of the owned value when the parent&#39;s own lifetime ends.\nThe parent (owner) could be in static storage for global constants, it could be another owned or even managed value, or it could be a call frame in a method (in which case we get a stack allocation).</p>\n<figure class=\"markdown-code\"><figcaption><span class=\"markdown-code__title\">Ownership</span><span class=\"markdown-code__format\">.ds</span></figcaption><pre tabindex=\"0\"><code class=\"markdown-code-lines\"><span class=\"markdown-code-line\"><span class=\"markdown-code-gutter\">1</span><span class=\"markdown-code-text\"><span data-k=\"keyword\">let</span> <span data-k=\"name\">user</span><span data-k=\"punct\">:</span> <span data-k=\"type\">User</span> <span data-k=\"punct\">=</span> <span data-k=\"keyword\">new</span> <span data-k=\"type\">User</span><span data-k=\"punct\">(</span><span data-k=\"punct\">)</span><span data-k=\"punct\">;</span>   <span data-k=\"comment\">// managed: the runtime owns it</span></span></span><span class=\"markdown-code-line\"><span class=\"markdown-code-gutter\">2</span><span class=\"markdown-code-text\"><span data-k=\"keyword\">let</span> <span data-k=\"name\">owned</span><span data-k=\"punct\">:</span> <span data-k=\"punct\">^</span><span data-k=\"type\">User</span> <span data-k=\"punct\">=</span> <span data-k=\"keyword\">new</span> <span data-k=\"type\">User</span><span data-k=\"punct\">(</span><span data-k=\"punct\">)</span><span data-k=\"punct\">;</span> <span data-k=\"comment\">// owned: this binding owns it, dropped after last use</span></span></span><span class=\"markdown-code-line\"><span class=\"markdown-code-gutter\">3</span><span class=\"markdown-code-text\"> </span></span><span class=\"markdown-code-line\"><span class=\"markdown-code-gutter\">4</span><span class=\"markdown-code-text\"><span data-k=\"keyword\">let</span> <span data-k=\"name\">borrow</span><span data-k=\"punct\">:</span> <span data-k=\"punct\">&amp;</span><span data-k=\"type\">User</span> <span data-k=\"punct\">=</span> <span data-k=\"punct\">&amp;</span><span data-k=\"name\">user</span><span data-k=\"punct\">;</span>                    <span data-k=\"comment\">// mutable borrow of the managed value</span></span></span><span class=\"markdown-code-line\"><span class=\"markdown-code-gutter\">5</span><span class=\"markdown-code-text\"><span data-k=\"keyword\">let</span> <span data-k=\"name\">view</span><span data-k=\"punct\">:</span> <span data-k=\"punct\">&amp;</span><span data-k=\"keyword\">readonly</span> <span data-k=\"type\">User</span> <span data-k=\"punct\">=</span> <span data-k=\"punct\">&amp;</span><span data-k=\"keyword\">readonly</span> <span data-k=\"name\">user</span><span data-k=\"punct\">;</span>    <span data-k=\"comment\">// OK: readonly may overlap the mutable borrow</span></span></span><span class=\"markdown-code-line\"><span class=\"markdown-code-gutter\">6</span><span class=\"markdown-code-text\"><span data-k=\"keyword\">let</span> <span data-k=\"name\">claim</span><span data-k=\"punct\">:</span> <span data-k=\"punct\">&amp;</span>exclusive <span data-k=\"type\">User</span> <span data-k=\"punct\">=</span> <span data-k=\"punct\">&amp;</span>exclusive <span data-k=\"name\">user</span><span data-k=\"punct\">;</span> <span data-k=\"comment\">// ERROR: `borrow` and `view` are still live</span></span></span><span class=\"markdown-code-line\"><span class=\"markdown-code-gutter\">7</span><span class=\"markdown-code-text\"><span data-k=\"keyword\">let</span> <span data-k=\"name\">pointer</span><span data-k=\"punct\">:</span> <span data-k=\"punct\">*</span><span data-k=\"type\">User</span> <span data-k=\"punct\">=</span> <span data-k=\"punct\">&amp;</span><span data-k=\"name\">user</span><span data-k=\"punct\">;</span>                   <span data-k=\"comment\">// OK: raw pointers are inert and unchecked</span></span></span></code></pre></figure><p>Each ownership form also has a corresponding normalized representation in our little <a href=\"#algebra\">&quot;type algebra&quot;</a>, which means we get to do regular TypeScript-style type space logic, conditionals and remapping (including for lifetimes!).</p>\n<h2 id=\"borrowing\">Borrowing</h2><p>To ensure memory safety even in unmanaged land, Destack follows the Rust idea of using ownership rules to ensure that <em>borrowing</em> a reference <code>&amp;T</code> remains valid - that is, <code>T</code> must remain alive (must not be deallocated) while <em>any</em> <code>&amp;T</code> is active.\nMuch more so than in Rust, Destack infers lifetimes for borrowed values even with complex control flow, so most of the time all lifetimes are inferred correctly and we don&#39;t need to think too much.</p>\n<p>Unlike in Rust, in Destack, mutability is decoupled from borrowing: we can have multiple mutable borrows <code>&amp;T</code> and readonly borrows <code>&amp;readonly T</code> of the same <code>T</code> <em>at the same time</em>, as long as there is no concurrent <code>&amp;exclusive T</code> borrow (which mirrors Rust&#39;s <code>&amp;mut T</code>).\nImportantly, this is still memory safe because all operations that may invalidate a borrow require <code>&amp;exclusive T</code> access.</p>\n<div class=\"markdown-table\" tabindex=\"0\"><table><thead><tr>\n<th>Form</th>\n<th>Access</th>\n</tr>\n</thead><tbody><tr>\n<td><code>&amp;readonly T</code></td>\n<td>may overlap, cannot mutate through the borrow</td>\n</tr>\n<tr>\n<td><code>&amp;T</code></td>\n<td>may overlap, can mutate through the borrow</td>\n</tr>\n<tr>\n<td><code>&amp;exclusive T</code></td>\n<td>cannot overlap another borrow of the same place, can mutate through the borrow</td>\n</tr>\n</tbody></table></div><p>Borrow checking is just rule 2 applied per &quot;access path&quot;, so disjoint fields can be borrowed independently when the compiler can prove they do not overlap.</p>\n<figure class=\"markdown-code\"><figcaption><span class=\"markdown-code__title\">Borrowing</span><span class=\"markdown-code__format\">.ds</span></figcaption><pre tabindex=\"0\"><code class=\"markdown-code-lines\"><span class=\"markdown-code-line\"><span class=\"markdown-code-gutter\">1</span><span class=\"markdown-code-text\"><span data-k=\"keyword\">struct</span> <span data-k=\"type\">Point</span> <span data-k=\"punct\">{</span></span></span><span class=\"markdown-code-line\"><span class=\"markdown-code-gutter\">2</span><span class=\"markdown-code-text\">    <span data-k=\"property\">x</span><span data-k=\"punct\">:</span> <span data-k=\"type\">int32</span><span data-k=\"punct\">;</span></span></span><span class=\"markdown-code-line\"><span class=\"markdown-code-gutter\">3</span><span class=\"markdown-code-text\">    <span data-k=\"property\">y</span><span data-k=\"punct\">:</span> <span data-k=\"type\">int32</span><span data-k=\"punct\">;</span></span></span><span class=\"markdown-code-line\"><span class=\"markdown-code-gutter\">4</span><span class=\"markdown-code-text\"><span data-k=\"punct\">}</span></span></span><span class=\"markdown-code-line\"><span class=\"markdown-code-gutter\">5</span><span class=\"markdown-code-text\"> </span></span><span class=\"markdown-code-line\"><span class=\"markdown-code-gutter\">6</span><span class=\"markdown-code-text\"><span data-k=\"keyword\">class</span> <span data-k=\"type\">User</span> <span data-k=\"punct\">{</span></span></span><span class=\"markdown-code-line\"><span class=\"markdown-code-gutter\">7</span><span class=\"markdown-code-text\">    <span data-k=\"property\">name</span><span data-k=\"punct\">:</span> <span data-k=\"type\">string</span> <span data-k=\"punct\">=</span> <span data-k=\"string\">&quot;&quot;</span><span data-k=\"punct\">;</span></span></span><span class=\"markdown-code-line\"><span class=\"markdown-code-gutter\">8</span><span class=\"markdown-code-text\"><span data-k=\"punct\">}</span></span></span><span class=\"markdown-code-line\"><span class=\"markdown-code-gutter\">9</span><span class=\"markdown-code-text\"> </span></span><span class=\"markdown-code-line\"><span class=\"markdown-code-gutter\">10</span><span class=\"markdown-code-text\"><span data-k=\"keyword\">let</span> <span data-k=\"name\">user</span><span data-k=\"punct\">:</span> <span data-k=\"type\">User</span> <span data-k=\"punct\">=</span> <span data-k=\"keyword\">new</span> <span data-k=\"type\">User</span><span data-k=\"punct\">(</span><span data-k=\"punct\">)</span><span data-k=\"punct\">;</span></span></span><span class=\"markdown-code-line\"><span class=\"markdown-code-gutter\">11</span><span class=\"markdown-code-text\"> </span></span><span class=\"markdown-code-line\"><span class=\"markdown-code-gutter\">12</span><span class=\"markdown-code-text\"><span data-k=\"comment\">// `&amp;user.name` borrows through the managed `User` handle</span></span></span><span class=\"markdown-code-line\"><span class=\"markdown-code-gutter\">13</span><span class=\"markdown-code-text\"><span data-k=\"keyword\">let</span> <span data-k=\"name\">name</span> <span data-k=\"punct\">=</span> <span data-k=\"punct\">&amp;</span><span data-k=\"name\">user</span><span data-k=\"punct\">.</span><span data-k=\"property\">name</span><span data-k=\"punct\">;</span></span></span><span class=\"markdown-code-line\"><span class=\"markdown-code-gutter\">14</span><span class=\"markdown-code-text\"> </span></span><span class=\"markdown-code-line\"><span class=\"markdown-code-gutter\">15</span><span class=\"markdown-code-text\"><span data-k=\"comment\">// `name` is borrowed access into managed storage</span></span></span><span class=\"markdown-code-line\"><span class=\"markdown-code-gutter\">16</span><span class=\"markdown-code-text\"><span data-k=\"name\">name</span> <span data-k=\"keyword\">satisfies</span> <span data-k=\"punct\">&amp;</span><span data-k=\"type\">string</span><span data-k=\"punct\">;</span></span></span><span class=\"markdown-code-line\"><span class=\"markdown-code-gutter\">17</span><span class=\"markdown-code-text\"> </span></span><span class=\"markdown-code-line\"><span class=\"markdown-code-gutter\">18</span><span class=\"markdown-code-text\"><span data-k=\"keyword\">let</span> <span data-k=\"name\">point</span> <span data-k=\"punct\">=</span> <span data-k=\"punct\">^</span><span data-k=\"type\">Point</span> <span data-k=\"punct\">{</span> <span data-k=\"property\">x</span><span data-k=\"punct\">:</span> <span data-k=\"literal\">1</span><span data-k=\"punct\">,</span> <span data-k=\"property\">y</span><span data-k=\"punct\">:</span> <span data-k=\"literal\">2</span> <span data-k=\"punct\">}</span><span data-k=\"punct\">;</span></span></span><span class=\"markdown-code-line\"><span class=\"markdown-code-gutter\">19</span><span class=\"markdown-code-text\"> </span></span><span class=\"markdown-code-line\"><span class=\"markdown-code-gutter\">20</span><span class=\"markdown-code-text\"><span data-k=\"comment\">// `&amp;readonly point.x` borrows from owned storage without moving `point`</span></span></span><span class=\"markdown-code-line\"><span class=\"markdown-code-gutter\">21</span><span class=\"markdown-code-text\"><span data-k=\"keyword\">let</span> <span data-k=\"name\">readX</span> <span data-k=\"punct\">=</span> <span data-k=\"punct\">&amp;</span><span data-k=\"keyword\">readonly</span> <span data-k=\"name\">point</span><span data-k=\"punct\">.</span><span data-k=\"property\">x</span><span data-k=\"punct\">;</span></span></span><span class=\"markdown-code-line\"><span class=\"markdown-code-gutter\">22</span><span class=\"markdown-code-text\"> </span></span><span class=\"markdown-code-line\"><span class=\"markdown-code-gutter\">23</span><span class=\"markdown-code-text\"><span data-k=\"comment\">// `&amp;point.x` *can* overlap with readonly borrowed access</span></span></span><span class=\"markdown-code-line\"><span class=\"markdown-code-gutter\">24</span><span class=\"markdown-code-text\"><span data-k=\"keyword\">let</span> <span data-k=\"name\">writeX</span> <span data-k=\"punct\">=</span> <span data-k=\"punct\">&amp;</span><span data-k=\"name\">point</span><span data-k=\"punct\">.</span><span data-k=\"property\">x</span><span data-k=\"punct\">;</span></span></span><span class=\"markdown-code-line\"><span class=\"markdown-code-gutter\">25</span><span class=\"markdown-code-text\"><span data-k=\"punct\">*</span><span data-k=\"name\">writeX</span> <span data-k=\"punct\">=</span> <span data-k=\"literal\">3</span><span data-k=\"punct\">;</span></span></span><span class=\"markdown-code-line\"><span class=\"markdown-code-gutter\">26</span><span class=\"markdown-code-text\"> </span></span><span class=\"markdown-code-line\"><span class=\"markdown-code-gutter\">27</span><span class=\"markdown-code-text\"><span data-k=\"comment\">// `&amp;point.y` mutably borrows a disjoint field</span></span></span><span class=\"markdown-code-line\"><span class=\"markdown-code-gutter\">28</span><span class=\"markdown-code-text\"><span data-k=\"keyword\">let</span> <span data-k=\"name\">writeY</span> <span data-k=\"punct\">=</span> <span data-k=\"punct\">&amp;</span><span data-k=\"name\">point</span><span data-k=\"punct\">.</span><span data-k=\"property\">y</span><span data-k=\"punct\">;</span></span></span><span class=\"markdown-code-line\"><span class=\"markdown-code-gutter\">29</span><span class=\"markdown-code-text\"><span data-k=\"punct\">*</span><span data-k=\"name\">writeY</span> <span data-k=\"punct\">=</span> <span data-k=\"literal\">3</span><span data-k=\"punct\">;</span></span></span><span class=\"markdown-code-line\"><span class=\"markdown-code-gutter\">30</span><span class=\"markdown-code-text\"> </span></span><span class=\"markdown-code-line\"><span class=\"markdown-code-gutter\">31</span><span class=\"markdown-code-text\"><span data-k=\"comment\">// the readonly borrow is still valid here</span></span></span><span class=\"markdown-code-line\"><span class=\"markdown-code-gutter\">32</span><span class=\"markdown-code-text\"><span data-k=\"name\">readX</span> <span data-k=\"keyword\">satisfies</span> <span data-k=\"punct\">&amp;</span><span data-k=\"keyword\">readonly</span> <span data-k=\"type\">int32</span><span data-k=\"punct\">;</span></span></span><span class=\"markdown-code-line\"><span class=\"markdown-code-gutter\">33</span><span class=\"markdown-code-text\"> </span></span><span class=\"markdown-code-line\"><span class=\"markdown-code-gutter\">34</span><span class=\"markdown-code-text\"><span data-k=\"comment\">// `&amp;exclusive point.x` is allowed after the overlapping borrows are no longer live</span></span></span><span class=\"markdown-code-line\"><span class=\"markdown-code-gutter\">35</span><span class=\"markdown-code-text\"><span data-k=\"keyword\">let</span> <span data-k=\"name\">exclusiveX</span> <span data-k=\"punct\">=</span> <span data-k=\"punct\">&amp;</span>exclusive <span data-k=\"name\">point</span><span data-k=\"punct\">.</span><span data-k=\"property\">x</span><span data-k=\"punct\">;</span></span></span><span class=\"markdown-code-line\"><span class=\"markdown-code-gutter\">36</span><span class=\"markdown-code-text\"><span data-k=\"punct\">*</span><span data-k=\"name\">exclusiveX</span> <span data-k=\"punct\">=</span> <span data-k=\"literal\">4</span><span data-k=\"punct\">;</span></span></span></code></pre></figure><h3 id=\"stability\">Stability</h3><p>Allowing multiple live mutable borrows is memory safe only because every operation that may <em>invalidate</em> another live borrow requires exclusivity (via <code>&amp;exclusive</code>).\nWriting through a non-exclusive borrow is therefore allowed only when that place is <strong>overwrite-stable</strong>: the old value requires no destruction (no <code>Drop</code>), and the new bytes mean what the old bytes meant (one fixed layout, no variant tag), both of which scalar and managed-reference fields trivially satisfy.\nEverything else requires <code>&amp;exclusive</code>: overwriting a variant reinterprets the payload under a live interior borrow, overwriting an owning value frees memory a borrow may still target, and so on.</p>\n<figure class=\"markdown-code\"><figcaption><span class=\"markdown-code__title\">Stability</span><span class=\"markdown-code__format\">.ds</span></figcaption><pre tabindex=\"0\"><code class=\"markdown-code-lines\"><span class=\"markdown-code-line\"><span class=\"markdown-code-gutter\">1</span><span class=\"markdown-code-text\"><span data-k=\"keyword\">struct</span> <span data-k=\"type\">Frame</span> <span data-k=\"punct\">{</span></span></span><span class=\"markdown-code-line\"><span class=\"markdown-code-gutter\">2</span><span class=\"markdown-code-text\">    <span data-k=\"property\">pixels</span><span data-k=\"punct\">:</span> <span data-k=\"punct\">^</span><span data-k=\"type\">Buffer</span><span data-k=\"punct\">;</span> <span data-k=\"comment\">// owned interior storage</span></span></span><span class=\"markdown-code-line\"><span class=\"markdown-code-gutter\">3</span><span class=\"markdown-code-text\"><span data-k=\"punct\">}</span></span></span><span class=\"markdown-code-line\"><span class=\"markdown-code-gutter\">4</span><span class=\"markdown-code-text\"> </span></span><span class=\"markdown-code-line\"><span class=\"markdown-code-gutter\">5</span><span class=\"markdown-code-text\"><span data-k=\"keyword\">let</span> <span data-k=\"name\">frame</span><span data-k=\"punct\">:</span> <span data-k=\"punct\">^</span><span data-k=\"type\">Frame</span> <span data-k=\"punct\">=</span> <span data-k=\"type\">Frame</span> <span data-k=\"punct\">{</span> <span data-k=\"property\">pixels</span><span data-k=\"punct\">:</span> <span data-k=\"type\">Buffer</span><span data-k=\"punct\">.</span><span data-k=\"property\">open</span><span data-k=\"punct\">(</span><span data-k=\"punct\">)</span> <span data-k=\"punct\">}</span><span data-k=\"punct\">;</span></span></span><span class=\"markdown-code-line\"><span class=\"markdown-code-gutter\">6</span><span class=\"markdown-code-text\"> </span></span><span class=\"markdown-code-line\"><span class=\"markdown-code-gutter\">7</span><span class=\"markdown-code-text\"><span data-k=\"keyword\">let</span> <span data-k=\"name\">pixels</span> <span data-k=\"punct\">=</span> <span data-k=\"punct\">&amp;</span><span data-k=\"name\">frame</span><span data-k=\"punct\">.</span><span data-k=\"property\">pixels</span><span data-k=\"punct\">;</span> <span data-k=\"comment\">// interior borrow into the owned buffer</span></span></span><span class=\"markdown-code-line\"><span class=\"markdown-code-gutter\">8</span><span class=\"markdown-code-text\"><span data-k=\"keyword\">let</span> <span data-k=\"name\">alias</span> <span data-k=\"punct\">=</span> <span data-k=\"punct\">&amp;</span><span data-k=\"name\">frame</span><span data-k=\"punct\">;</span>         <span data-k=\"comment\">// non-exclusive borrows may overlap</span></span></span><span class=\"markdown-code-line\"><span class=\"markdown-code-gutter\">9</span><span class=\"markdown-code-text\"> </span></span><span class=\"markdown-code-line\"><span class=\"markdown-code-gutter\">10</span><span class=\"markdown-code-text\"><span data-k=\"punct\">*</span><span data-k=\"name\">alias</span> <span data-k=\"punct\">=</span> <span data-k=\"type\">Frame</span> <span data-k=\"punct\">{</span> <span data-k=\"property\">pixels</span><span data-k=\"punct\">:</span> <span data-k=\"type\">Buffer</span><span data-k=\"punct\">.</span><span data-k=\"property\">open</span><span data-k=\"punct\">(</span><span data-k=\"punct\">)</span> <span data-k=\"punct\">}</span><span data-k=\"punct\">;</span> <span data-k=\"comment\">// ERROR: overwrite drops the old buffer under `pixels`</span></span></span></code></pre></figure><p>It should be noted that as with the rest of borrowing and ownership, <em>regular</em> managed land needs to know about exactly zero of this because managed handles alias freely and mutably.\nWrites through one managed handle can at most result in <em>stale</em> reads through another (a &quot;borrow&quot; into an array taken before it grew still reads the old buffer), which is just ordinary TypeScript aliasing, and not really a memory safety problem in itself.</p>\n<h3 id=\"rooting\">Rooting</h3><p>Borrows into managed storage stay valid via something we call &quot;automatic rooting&quot;: the compiler remembers every managed handle a borrow needs via a hidden frame slot that keeps it alive until the borrow&#39;s last use (and the collector scans that slot like any other handle local).\nThis is essentially what we always want anyway, and it lets the GC not worry about interior borrows <em>at all</em>: no write can invalidate a borrow rooted in managed storage since overwriting the path the borrow came through leaves the old object alive.</p>\n<figure class=\"markdown-code\"><figcaption><span class=\"markdown-code__title\">Rooting</span><span class=\"markdown-code__format\">.ds</span></figcaption><pre tabindex=\"0\"><code class=\"markdown-code-lines\"><span class=\"markdown-code-line\"><span class=\"markdown-code-gutter\">1</span><span class=\"markdown-code-text\"><span data-k=\"keyword\">class</span> <span data-k=\"type\">Profile</span> <span data-k=\"punct\">{</span></span></span><span class=\"markdown-code-line\"><span class=\"markdown-code-gutter\">2</span><span class=\"markdown-code-text\">    <span data-k=\"property\">name</span><span data-k=\"punct\">:</span> <span data-k=\"type\">string</span><span data-k=\"punct\">;</span></span></span><span class=\"markdown-code-line\"><span class=\"markdown-code-gutter\">3</span><span class=\"markdown-code-text\"><span data-k=\"punct\">}</span></span></span><span class=\"markdown-code-line\"><span class=\"markdown-code-gutter\">4</span><span class=\"markdown-code-text\"> </span></span><span class=\"markdown-code-line\"><span class=\"markdown-code-gutter\">5</span><span class=\"markdown-code-text\"><span data-k=\"keyword\">class</span> <span data-k=\"type\">User</span> <span data-k=\"punct\">{</span></span></span><span class=\"markdown-code-line\"><span class=\"markdown-code-gutter\">6</span><span class=\"markdown-code-text\">    <span data-k=\"property\">profile</span><span data-k=\"punct\">:</span> <span data-k=\"type\">Profile</span><span data-k=\"punct\">;</span></span></span><span class=\"markdown-code-line\"><span class=\"markdown-code-gutter\">7</span><span class=\"markdown-code-text\"><span data-k=\"punct\">}</span></span></span><span class=\"markdown-code-line\"><span class=\"markdown-code-gutter\">8</span><span class=\"markdown-code-text\"> </span></span><span class=\"markdown-code-line\"><span class=\"markdown-code-gutter\">9</span><span class=\"markdown-code-text\"><span data-k=\"keyword\">let</span> <span data-k=\"name\">name</span> <span data-k=\"punct\">=</span> <span data-k=\"punct\">&amp;</span><span data-k=\"name\">user</span><span data-k=\"punct\">.</span><span data-k=\"property\">profile</span><span data-k=\"punct\">.</span><span data-k=\"property\">name</span><span data-k=\"punct\">;</span>          <span data-k=\"comment\">// roots the `user.profile` handle</span></span></span><span class=\"markdown-code-line\"><span class=\"markdown-code-gutter\">10</span><span class=\"markdown-code-text\"><span data-k=\"name\">user</span><span data-k=\"punct\">.</span><span data-k=\"property\">profile</span> <span data-k=\"punct\">=</span> <span data-k=\"keyword\">new</span> <span data-k=\"type\">Profile</span><span data-k=\"punct\">(</span><span data-k=\"string\">&quot;other&quot;</span><span data-k=\"punct\">)</span><span data-k=\"punct\">;</span>    <span data-k=\"comment\">// OK: the old profile stays pinned</span></span></span><span class=\"markdown-code-line\"><span class=\"markdown-code-gutter\">11</span><span class=\"markdown-code-text\"><span data-k=\"function\">print</span><span data-k=\"punct\">(</span><span data-k=\"punct\">*</span><span data-k=\"name\">name</span><span data-k=\"punct\">)</span><span data-k=\"punct\">;</span>                           <span data-k=\"comment\">// still reads the borrowed profile</span></span></span></code></pre></figure><p>The hidden slot is just a compiler temporary, and borrows of temporaries follow the same extension rules as Rust: a borrow that initializes a binding extends its temporary to the binding&#39;s lifetime, and any other temporary lives to the end of the enclosing statement.</p>\n<h3 id=\"definite-assignment\">Definite Assignment</h3><p>In general, all binding must be definitely assigned to <em>something</em> before they can be used in any way (read, moved, borrowed, returned, or implicitly dropped):</p>\n<figure class=\"markdown-code\"><figcaption><span class=\"markdown-code__title\">Definite Assignment</span><span class=\"markdown-code__format\">.ds</span></figcaption><pre tabindex=\"0\"><code class=\"markdown-code-lines\"><span class=\"markdown-code-line\"><span class=\"markdown-code-gutter\">1</span><span class=\"markdown-code-text\"><span data-k=\"keyword\">let</span> <span data-k=\"name\">value</span><span data-k=\"punct\">:</span> <span data-k=\"type\">Buffer</span><span data-k=\"punct\">;</span></span></span><span class=\"markdown-code-line\"><span class=\"markdown-code-gutter\">2</span><span class=\"markdown-code-text\"> </span></span><span class=\"markdown-code-line\"><span class=\"markdown-code-gutter\">3</span><span class=\"markdown-code-text\"><span data-k=\"keyword\">if</span> <span data-k=\"punct\">(</span><span data-k=\"name\">enabled</span><span data-k=\"punct\">)</span> <span data-k=\"punct\">{</span></span></span><span class=\"markdown-code-line\"><span class=\"markdown-code-gutter\">4</span><span class=\"markdown-code-text\">    <span data-k=\"name\">value</span> <span data-k=\"punct\">=</span> <span data-k=\"type\">Buffer</span><span data-k=\"punct\">.</span><span data-k=\"property\">open</span><span data-k=\"punct\">(</span><span data-k=\"punct\">)</span><span data-k=\"punct\">;</span></span></span><span class=\"markdown-code-line\"><span class=\"markdown-code-gutter\">5</span><span class=\"markdown-code-text\"><span data-k=\"punct\">}</span></span></span><span class=\"markdown-code-line\"><span class=\"markdown-code-gutter\">6</span><span class=\"markdown-code-text\"> </span></span><span class=\"markdown-code-line\"><span class=\"markdown-code-gutter\">7</span><span class=\"markdown-code-text\"><span data-k=\"function\">process</span><span data-k=\"punct\">(</span><span data-k=\"name\">value</span><span data-k=\"punct\">)</span><span data-k=\"punct\">;</span> <span data-k=\"comment\">// ERROR: `value` is not assigned on every path</span></span></span></code></pre></figure><p>When &quot;maybe&quot; state is explicitly desired, we can represent it with a nullish union (or any other union as needed)_</p>\n<figure class=\"markdown-code\"><figcaption><span class=\"markdown-code__title\">Definite Assignment</span><span class=\"markdown-code__format\">.ds</span></figcaption><pre tabindex=\"0\"><code class=\"markdown-code-lines\"><span class=\"markdown-code-line\"><span class=\"markdown-code-gutter\">1</span><span class=\"markdown-code-text\"><span data-k=\"keyword\">let</span> <span data-k=\"name\">value</span><span data-k=\"punct\">:</span> <span data-k=\"type\">Buffer</span> <span data-k=\"punct\">|</span> <span data-k=\"literal\">undefined</span><span data-k=\"punct\">;</span></span></span><span class=\"markdown-code-line\"><span class=\"markdown-code-gutter\">2</span><span class=\"markdown-code-text\"> </span></span><span class=\"markdown-code-line\"><span class=\"markdown-code-gutter\">3</span><span class=\"markdown-code-text\"><span data-k=\"keyword\">if</span> <span data-k=\"punct\">(</span><span data-k=\"name\">enabled</span><span data-k=\"punct\">)</span> <span data-k=\"punct\">{</span></span></span><span class=\"markdown-code-line\"><span class=\"markdown-code-gutter\">4</span><span class=\"markdown-code-text\">    <span data-k=\"name\">value</span> <span data-k=\"punct\">=</span> <span data-k=\"type\">Buffer</span><span data-k=\"punct\">.</span><span data-k=\"property\">open</span><span data-k=\"punct\">(</span><span data-k=\"punct\">)</span><span data-k=\"punct\">;</span></span></span><span class=\"markdown-code-line\"><span class=\"markdown-code-gutter\">5</span><span class=\"markdown-code-text\"><span data-k=\"punct\">}</span></span></span><span class=\"markdown-code-line\"><span class=\"markdown-code-gutter\">6</span><span class=\"markdown-code-text\"> </span></span><span class=\"markdown-code-line\"><span class=\"markdown-code-gutter\">7</span><span class=\"markdown-code-text\"><span data-k=\"keyword\">if</span> <span data-k=\"punct\">(</span><span data-k=\"name\">value</span> <span data-k=\"punct\">!=</span> <span data-k=\"literal\">undefined</span><span data-k=\"punct\">)</span> <span data-k=\"punct\">{</span></span></span><span class=\"markdown-code-line\"><span class=\"markdown-code-gutter\">8</span><span class=\"markdown-code-text\">    <span data-k=\"function\">process</span><span data-k=\"punct\">(</span><span data-k=\"name\">value</span><span data-k=\"punct\">)</span><span data-k=\"punct\">;</span></span></span><span class=\"markdown-code-line\"><span class=\"markdown-code-gutter\">9</span><span class=\"markdown-code-text\"><span data-k=\"punct\">}</span></span></span></code></pre></figure><h2 id=\"lifetimes\">Lifetimes</h2><p>Lifetimes tie a borrow to its source, and in Destack they are just generics: <code>&lt;comptime L: Lifetime&gt;</code> parameters on <code>Borrowed&lt;T, L&gt;</code>, available to all the regular TypeScript-style type algebra and inference (including flow typing and narrowing).\nLike <code>Access</code>, <code>Space</code>, and <code>Place</code>, <code>Lifetime</code> is a kind of static <em>value</em> rather than a type, which is why parameters over these forms always carry the <code>comptime</code> modifier.\nIn practice they are spelled out in exactly one place - <code>declare</code> signatures - and inferred everywhere else, including from function bodies.</p>\n<figure class=\"markdown-code\"><figcaption><span class=\"markdown-code__title\">Lifetimes</span><span class=\"markdown-code__format\">.ds</span></figcaption><pre tabindex=\"0\"><code class=\"markdown-code-lines\"><span class=\"markdown-code-line\"><span class=\"markdown-code-gutter\">1</span><span class=\"markdown-code-text\"><span data-k=\"keyword\">function</span> <span data-k=\"function\">read</span><span data-k=\"punct\">(</span><span data-k=\"name\">user</span><span data-k=\"punct\">:</span> <span data-k=\"punct\">&amp;</span><span data-k=\"type\">User</span><span data-k=\"punct\">)</span><span data-k=\"punct\">:</span> <span data-k=\"punct\">&amp;</span><span data-k=\"type\">string</span> <span data-k=\"punct\">{</span></span></span><span class=\"markdown-code-line\"><span class=\"markdown-code-gutter\">2</span><span class=\"markdown-code-text\">    <span data-k=\"keyword\">return</span> <span data-k=\"punct\">&amp;</span><span data-k=\"name\">user</span><span data-k=\"punct\">.</span><span data-k=\"property\">name</span><span data-k=\"punct\">;</span></span></span><span class=\"markdown-code-line\"><span class=\"markdown-code-gutter\">3</span><span class=\"markdown-code-text\"><span data-k=\"punct\">}</span></span></span><span class=\"markdown-code-line\"><span class=\"markdown-code-gutter\">4</span><span class=\"markdown-code-text\"> </span></span><span class=\"markdown-code-line\"><span class=\"markdown-code-gutter\">5</span><span class=\"markdown-code-text\"><span data-k=\"keyword\">function</span> <span data-k=\"function\">first</span><span data-k=\"punct\">&lt;</span><span data-k=\"type\">T</span><span data-k=\"punct\">&gt;</span><span data-k=\"punct\">(</span><span data-k=\"name\">items</span><span data-k=\"punct\">:</span> <span data-k=\"punct\">&amp;</span><span data-k=\"punct\">[</span><span data-k=\"type\">T</span><span data-k=\"punct\">]</span><span data-k=\"punct\">)</span><span data-k=\"punct\">:</span> <span data-k=\"punct\">&amp;</span><span data-k=\"type\">T</span> <span data-k=\"punct\">{</span></span></span><span class=\"markdown-code-line\"><span class=\"markdown-code-gutter\">6</span><span class=\"markdown-code-text\">    <span data-k=\"keyword\">return</span> <span data-k=\"punct\">&amp;</span><span data-k=\"name\">items</span><span data-k=\"punct\">[</span><span data-k=\"literal\">0</span><span data-k=\"punct\">]</span><span data-k=\"punct\">;</span></span></span><span class=\"markdown-code-line\"><span class=\"markdown-code-gutter\">7</span><span class=\"markdown-code-text\"><span data-k=\"punct\">}</span></span></span></code></pre></figure><p>Elided borrowed forms get hidden generic lifetime parameters in <em>all</em> declarations, not just in function signatures.</p>\n<figure class=\"markdown-code\"><figcaption><span class=\"markdown-code__title\">Lifetimes</span><span class=\"markdown-code__format\">.ds</span></figcaption><pre tabindex=\"0\"><code class=\"markdown-code-lines\"><span class=\"markdown-code-line\"><span class=\"markdown-code-gutter\">1</span><span class=\"markdown-code-text\"><span data-k=\"comment\">// elided form</span></span></span><span class=\"markdown-code-line\"><span class=\"markdown-code-gutter\">2</span><span class=\"markdown-code-text\"><span data-k=\"keyword\">struct</span> <span data-k=\"type\">WorldView</span> <span data-k=\"punct\">{</span></span></span><span class=\"markdown-code-line\"><span class=\"markdown-code-gutter\">3</span><span class=\"markdown-code-text\">    <span data-k=\"property\">engine</span><span data-k=\"punct\">:</span> <span data-k=\"punct\">&amp;</span><span data-k=\"type\">Engine</span><span data-k=\"punct\">;</span></span></span><span class=\"markdown-code-line\"><span class=\"markdown-code-gutter\">4</span><span class=\"markdown-code-text\">    <span data-k=\"property\">assets</span><span data-k=\"punct\">:</span> <span data-k=\"punct\">&amp;</span><span data-k=\"type\">AssetStore</span><span data-k=\"punct\">;</span></span></span><span class=\"markdown-code-line\"><span class=\"markdown-code-gutter\">5</span><span class=\"markdown-code-text\"><span data-k=\"punct\">}</span></span></span><span class=\"markdown-code-line\"><span class=\"markdown-code-gutter\">6</span><span class=\"markdown-code-text\"> </span></span><span class=\"markdown-code-line\"><span class=\"markdown-code-gutter\">7</span><span class=\"markdown-code-text\"><span data-k=\"comment\">// explicit form</span></span></span><span class=\"markdown-code-line\"><span class=\"markdown-code-gutter\">8</span><span class=\"markdown-code-text\"><span data-k=\"keyword\">struct</span> <span data-k=\"type\">WorldView</span><span data-k=\"punct\">&lt;</span><span data-k=\"keyword\">comptime</span> <span data-k=\"type\">L1</span><span data-k=\"punct\">:</span> <span data-k=\"type\">Lifetime</span><span data-k=\"punct\">,</span> <span data-k=\"keyword\">comptime</span> <span data-k=\"type\">L2</span><span data-k=\"punct\">:</span> <span data-k=\"type\">Lifetime</span><span data-k=\"punct\">&gt;</span> <span data-k=\"punct\">{</span></span></span><span class=\"markdown-code-line\"><span class=\"markdown-code-gutter\">9</span><span class=\"markdown-code-text\">    <span data-k=\"property\">engine</span><span data-k=\"punct\">:</span> <span data-k=\"type\">Borrowed</span><span data-k=\"punct\">&lt;</span><span data-k=\"type\">Engine</span><span data-k=\"punct\">,</span> <span data-k=\"type\">L1</span><span data-k=\"punct\">&gt;</span><span data-k=\"punct\">;</span></span></span><span class=\"markdown-code-line\"><span class=\"markdown-code-gutter\">10</span><span class=\"markdown-code-text\">    <span data-k=\"property\">assets</span><span data-k=\"punct\">:</span> <span data-k=\"type\">Borrowed</span><span data-k=\"punct\">&lt;</span><span data-k=\"type\">AssetStore</span><span data-k=\"punct\">,</span> <span data-k=\"type\">L2</span><span data-k=\"punct\">&gt;</span><span data-k=\"punct\">;</span></span></span><span class=\"markdown-code-line\"><span class=\"markdown-code-gutter\">11</span><span class=\"markdown-code-text\"><span data-k=\"punct\">}</span></span></span></code></pre></figure><p>Because lifetimes are part of type inference, and type inference also analyzes method bodies, lifetime inference also derives from function bodies.\nEach elided borrow in the signature induces its own hidden lifetime parameter first, and the body then solves the return lifetime:</p>\n<figure class=\"markdown-code\"><figcaption><span class=\"markdown-code__title\">Lifetimes</span><span class=\"markdown-code__format\">.ds</span></figcaption><pre tabindex=\"0\"><code class=\"markdown-code-lines\"><span class=\"markdown-code-line\"><span class=\"markdown-code-gutter\">1</span><span class=\"markdown-code-text\"><span data-k=\"comment\">// elided form</span></span></span><span class=\"markdown-code-line\"><span class=\"markdown-code-gutter\">2</span><span class=\"markdown-code-text\"><span data-k=\"keyword\">function</span> <span data-k=\"function\">first</span><span data-k=\"punct\">(</span><span data-k=\"name\">a</span><span data-k=\"punct\">:</span> <span data-k=\"punct\">&amp;</span><span data-k=\"type\">Node</span><span data-k=\"punct\">,</span> <span data-k=\"name\">b</span><span data-k=\"punct\">:</span> <span data-k=\"punct\">&amp;</span><span data-k=\"type\">Node</span><span data-k=\"punct\">)</span><span data-k=\"punct\">:</span> <span data-k=\"punct\">&amp;</span><span data-k=\"type\">Node</span> <span data-k=\"punct\">{</span></span></span><span class=\"markdown-code-line\"><span class=\"markdown-code-gutter\">3</span><span class=\"markdown-code-text\">    <span data-k=\"keyword\">return</span> <span data-k=\"name\">a</span><span data-k=\"punct\">;</span></span></span><span class=\"markdown-code-line\"><span class=\"markdown-code-gutter\">4</span><span class=\"markdown-code-text\"><span data-k=\"punct\">}</span></span></span><span class=\"markdown-code-line\"><span class=\"markdown-code-gutter\">5</span><span class=\"markdown-code-text\"> </span></span><span class=\"markdown-code-line\"><span class=\"markdown-code-gutter\">6</span><span class=\"markdown-code-text\"><span data-k=\"comment\">// explicit form</span></span></span><span class=\"markdown-code-line\"><span class=\"markdown-code-gutter\">7</span><span class=\"markdown-code-text\"><span data-k=\"keyword\">function</span> <span data-k=\"function\">first</span><span data-k=\"punct\">&lt;</span><span data-k=\"keyword\">comptime</span> <span data-k=\"type\">L1</span><span data-k=\"punct\">:</span> <span data-k=\"type\">Lifetime</span><span data-k=\"punct\">,</span> <span data-k=\"keyword\">comptime</span> <span data-k=\"type\">L2</span><span data-k=\"punct\">:</span> <span data-k=\"type\">Lifetime</span><span data-k=\"punct\">&gt;</span><span data-k=\"punct\">(</span></span></span><span class=\"markdown-code-line\"><span class=\"markdown-code-gutter\">8</span><span class=\"markdown-code-text\">    <span data-k=\"name\">a</span><span data-k=\"punct\">:</span> <span data-k=\"type\">Borrowed</span><span data-k=\"punct\">&lt;</span><span data-k=\"type\">Node</span><span data-k=\"punct\">,</span> <span data-k=\"type\">L1</span><span data-k=\"punct\">&gt;</span><span data-k=\"punct\">,</span></span></span><span class=\"markdown-code-line\"><span class=\"markdown-code-gutter\">9</span><span class=\"markdown-code-text\">    <span data-k=\"name\">b</span><span data-k=\"punct\">:</span> <span data-k=\"type\">Borrowed</span><span data-k=\"punct\">&lt;</span><span data-k=\"type\">Node</span><span data-k=\"punct\">,</span> <span data-k=\"type\">L2</span><span data-k=\"punct\">&gt;</span><span data-k=\"punct\">,</span></span></span><span class=\"markdown-code-line\"><span class=\"markdown-code-gutter\">10</span><span class=\"markdown-code-text\"><span data-k=\"punct\">)</span><span data-k=\"punct\">:</span> <span data-k=\"type\">Borrowed</span><span data-k=\"punct\">&lt;</span><span data-k=\"type\">Node</span><span data-k=\"punct\">,</span> <span data-k=\"type\">L1</span><span data-k=\"punct\">&gt;</span> <span data-k=\"punct\">{</span></span></span><span class=\"markdown-code-line\"><span class=\"markdown-code-gutter\">11</span><span class=\"markdown-code-text\">    <span data-k=\"keyword\">return</span> <span data-k=\"name\">a</span><span data-k=\"punct\">;</span></span></span><span class=\"markdown-code-line\"><span class=\"markdown-code-gutter\">12</span><span class=\"markdown-code-text\"><span data-k=\"punct\">}</span></span></span><span class=\"markdown-code-line\"><span class=\"markdown-code-gutter\">13</span><span class=\"markdown-code-text\"> </span></span><span class=\"markdown-code-line\"><span class=\"markdown-code-gutter\">14</span><span class=\"markdown-code-text\"><span data-k=\"comment\">// elided form</span></span></span><span class=\"markdown-code-line\"><span class=\"markdown-code-gutter\">15</span><span class=\"markdown-code-text\"><span data-k=\"keyword\">function</span> <span data-k=\"function\">choose</span><span data-k=\"punct\">(</span><span data-k=\"name\">a</span><span data-k=\"punct\">:</span> <span data-k=\"punct\">&amp;</span><span data-k=\"type\">Node</span><span data-k=\"punct\">,</span> <span data-k=\"name\">b</span><span data-k=\"punct\">:</span> <span data-k=\"punct\">&amp;</span><span data-k=\"type\">Node</span><span data-k=\"punct\">,</span> <span data-k=\"name\">flag</span><span data-k=\"punct\">:</span> <span data-k=\"type\">boolean</span><span data-k=\"punct\">)</span><span data-k=\"punct\">:</span> <span data-k=\"punct\">&amp;</span><span data-k=\"type\">Node</span> <span data-k=\"punct\">{</span></span></span><span class=\"markdown-code-line\"><span class=\"markdown-code-gutter\">16</span><span class=\"markdown-code-text\">    <span data-k=\"keyword\">return</span> <span data-k=\"name\">flag</span> <span data-k=\"punct\">?</span> <span data-k=\"name\">a</span> <span data-k=\"punct\">:</span> <span data-k=\"name\">b</span><span data-k=\"punct\">;</span></span></span><span class=\"markdown-code-line\"><span class=\"markdown-code-gutter\">17</span><span class=\"markdown-code-text\"><span data-k=\"punct\">}</span></span></span><span class=\"markdown-code-line\"><span class=\"markdown-code-gutter\">18</span><span class=\"markdown-code-text\"> </span></span><span class=\"markdown-code-line\"><span class=\"markdown-code-gutter\">19</span><span class=\"markdown-code-text\"><span data-k=\"comment\">// explicit form</span></span></span><span class=\"markdown-code-line\"><span class=\"markdown-code-gutter\">20</span><span class=\"markdown-code-text\"><span data-k=\"keyword\">function</span> <span data-k=\"function\">choose</span><span data-k=\"punct\">&lt;</span><span data-k=\"keyword\">comptime</span> <span data-k=\"type\">L1</span><span data-k=\"punct\">:</span> <span data-k=\"type\">Lifetime</span><span data-k=\"punct\">,</span> <span data-k=\"keyword\">comptime</span> <span data-k=\"type\">L2</span><span data-k=\"punct\">:</span> <span data-k=\"type\">Lifetime</span><span data-k=\"punct\">&gt;</span><span data-k=\"punct\">(</span></span></span><span class=\"markdown-code-line\"><span class=\"markdown-code-gutter\">21</span><span class=\"markdown-code-text\">    <span data-k=\"name\">a</span><span data-k=\"punct\">:</span> <span data-k=\"type\">Borrowed</span><span data-k=\"punct\">&lt;</span><span data-k=\"type\">Node</span><span data-k=\"punct\">,</span> <span data-k=\"type\">L1</span><span data-k=\"punct\">&gt;</span><span data-k=\"punct\">,</span></span></span><span class=\"markdown-code-line\"><span class=\"markdown-code-gutter\">22</span><span class=\"markdown-code-text\">    <span data-k=\"name\">b</span><span data-k=\"punct\">:</span> <span data-k=\"type\">Borrowed</span><span data-k=\"punct\">&lt;</span><span data-k=\"type\">Node</span><span data-k=\"punct\">,</span> <span data-k=\"type\">L2</span><span data-k=\"punct\">&gt;</span><span data-k=\"punct\">,</span></span></span><span class=\"markdown-code-line\"><span class=\"markdown-code-gutter\">23</span><span class=\"markdown-code-text\">    <span data-k=\"name\">flag</span><span data-k=\"punct\">:</span> <span data-k=\"type\">boolean</span><span data-k=\"punct\">,</span></span></span><span class=\"markdown-code-line\"><span class=\"markdown-code-gutter\">24</span><span class=\"markdown-code-text\"><span data-k=\"punct\">)</span><span data-k=\"punct\">:</span> <span data-k=\"type\">Borrowed</span><span data-k=\"punct\">&lt;</span><span data-k=\"type\">Node</span><span data-k=\"punct\">,</span> <span data-k=\"type\">L1</span> <span data-k=\"punct\">|</span> <span data-k=\"type\">L2</span><span data-k=\"punct\">&gt;</span> <span data-k=\"punct\">{</span></span></span><span class=\"markdown-code-line\"><span class=\"markdown-code-gutter\">25</span><span class=\"markdown-code-text\">    <span data-k=\"keyword\">return</span> <span data-k=\"name\">flag</span> <span data-k=\"punct\">?</span> <span data-k=\"name\">a</span> <span data-k=\"punct\">:</span> <span data-k=\"name\">b</span><span data-k=\"punct\">;</span></span></span><span class=\"markdown-code-line\"><span class=\"markdown-code-gutter\">26</span><span class=\"markdown-code-text\"><span data-k=\"punct\">}</span></span></span></code></pre></figure><p>Because <code>declare</code> functions do not have bodies, it follows that declaration-only APIs must spell out lifetime relationships explicitly.</p>\n<figure class=\"markdown-code\"><figcaption><span class=\"markdown-code__title\">Lifetimes</span><span class=\"markdown-code__format\">.ds</span></figcaption><pre tabindex=\"0\"><code class=\"markdown-code-lines\"><span class=\"markdown-code-line\"><span class=\"markdown-code-gutter\">1</span><span class=\"markdown-code-text\"><span data-k=\"comment\">// rejected</span></span></span><span class=\"markdown-code-line\"><span class=\"markdown-code-gutter\">2</span><span class=\"markdown-code-text\"><span data-k=\"keyword\">declare</span> <span data-k=\"keyword\">function</span> <span data-k=\"name\">only</span><span data-k=\"punct\">(</span><span data-k=\"name\">value</span><span data-k=\"punct\">:</span> <span data-k=\"punct\">&amp;</span><span data-k=\"type\">Node</span><span data-k=\"punct\">)</span><span data-k=\"punct\">:</span> <span data-k=\"punct\">&amp;</span><span data-k=\"type\">Node</span><span data-k=\"punct\">;</span></span></span><span class=\"markdown-code-line\"><span class=\"markdown-code-gutter\">3</span><span class=\"markdown-code-text\"> </span></span><span class=\"markdown-code-line\"><span class=\"markdown-code-gutter\">4</span><span class=\"markdown-code-text\"><span data-k=\"comment\">// accepted</span></span></span><span class=\"markdown-code-line\"><span class=\"markdown-code-gutter\">5</span><span class=\"markdown-code-text\"><span data-k=\"keyword\">declare</span> <span data-k=\"keyword\">function</span> <span data-k=\"name\">only</span><span data-k=\"punct\">&lt;</span><span data-k=\"keyword\">comptime</span> <span data-k=\"type\">L</span><span data-k=\"punct\">:</span> <span data-k=\"type\">Lifetime</span><span data-k=\"punct\">&gt;</span><span data-k=\"punct\">(</span><span data-k=\"name\">value</span><span data-k=\"punct\">:</span> <span data-k=\"type\">Borrowed</span><span data-k=\"punct\">&lt;</span><span data-k=\"type\">Node</span><span data-k=\"punct\">,</span> <span data-k=\"type\">L</span><span data-k=\"punct\">&gt;</span><span data-k=\"punct\">)</span><span data-k=\"punct\">:</span> <span data-k=\"type\">Borrowed</span><span data-k=\"punct\">&lt;</span><span data-k=\"type\">Node</span><span data-k=\"punct\">,</span> <span data-k=\"type\">L</span><span data-k=\"punct\">&gt;</span><span data-k=\"punct\">;</span></span></span><span class=\"markdown-code-line\"><span class=\"markdown-code-gutter\">6</span><span class=\"markdown-code-text\"> </span></span><span class=\"markdown-code-line\"><span class=\"markdown-code-gutter\">7</span><span class=\"markdown-code-text\"><span data-k=\"comment\">// rejected</span></span></span><span class=\"markdown-code-line\"><span class=\"markdown-code-gutter\">8</span><span class=\"markdown-code-text\"><span data-k=\"keyword\">declare</span> <span data-k=\"keyword\">function</span> <span data-k=\"name\">choose</span><span data-k=\"punct\">(</span></span></span><span class=\"markdown-code-line\"><span class=\"markdown-code-gutter\">9</span><span class=\"markdown-code-text\">    <span data-k=\"name\">a</span><span data-k=\"punct\">:</span> <span data-k=\"punct\">&amp;</span><span data-k=\"type\">Node</span><span data-k=\"punct\">,</span></span></span><span class=\"markdown-code-line\"><span class=\"markdown-code-gutter\">10</span><span class=\"markdown-code-text\">    <span data-k=\"name\">b</span><span data-k=\"punct\">:</span> <span data-k=\"punct\">&amp;</span><span data-k=\"type\">Node</span><span data-k=\"punct\">,</span></span></span><span class=\"markdown-code-line\"><span class=\"markdown-code-gutter\">11</span><span class=\"markdown-code-text\"><span data-k=\"punct\">)</span><span data-k=\"punct\">:</span> <span data-k=\"punct\">&amp;</span><span data-k=\"type\">Node</span><span data-k=\"punct\">;</span></span></span><span class=\"markdown-code-line\"><span class=\"markdown-code-gutter\">12</span><span class=\"markdown-code-text\"> </span></span><span class=\"markdown-code-line\"><span class=\"markdown-code-gutter\">13</span><span class=\"markdown-code-text\"><span data-k=\"comment\">// accepted</span></span></span><span class=\"markdown-code-line\"><span class=\"markdown-code-gutter\">14</span><span class=\"markdown-code-text\"><span data-k=\"keyword\">declare</span> <span data-k=\"keyword\">function</span> <span data-k=\"name\">choose</span><span data-k=\"punct\">&lt;</span><span data-k=\"keyword\">comptime</span> <span data-k=\"type\">L1</span><span data-k=\"punct\">:</span> <span data-k=\"type\">Lifetime</span><span data-k=\"punct\">,</span> <span data-k=\"keyword\">comptime</span> <span data-k=\"type\">L2</span><span data-k=\"punct\">:</span> <span data-k=\"type\">Lifetime</span><span data-k=\"punct\">&gt;</span><span data-k=\"punct\">(</span></span></span><span class=\"markdown-code-line\"><span class=\"markdown-code-gutter\">15</span><span class=\"markdown-code-text\">    <span data-k=\"name\">a</span><span data-k=\"punct\">:</span> <span data-k=\"type\">Borrowed</span><span data-k=\"punct\">&lt;</span><span data-k=\"type\">Node</span><span data-k=\"punct\">,</span> <span data-k=\"type\">L1</span><span data-k=\"punct\">&gt;</span><span data-k=\"punct\">,</span></span></span><span class=\"markdown-code-line\"><span class=\"markdown-code-gutter\">16</span><span class=\"markdown-code-text\">    <span data-k=\"name\">b</span><span data-k=\"punct\">:</span> <span data-k=\"type\">Borrowed</span><span data-k=\"punct\">&lt;</span><span data-k=\"type\">Node</span><span data-k=\"punct\">,</span> <span data-k=\"type\">L2</span><span data-k=\"punct\">&gt;</span><span data-k=\"punct\">,</span></span></span><span class=\"markdown-code-line\"><span class=\"markdown-code-gutter\">17</span><span class=\"markdown-code-text\"><span data-k=\"punct\">)</span><span data-k=\"punct\">:</span> <span data-k=\"type\">Borrowed</span><span data-k=\"punct\">&lt;</span><span data-k=\"type\">Node</span><span data-k=\"punct\">,</span> <span data-k=\"type\">L1</span> <span data-k=\"punct\">|</span> <span data-k=\"type\">L2</span><span data-k=\"punct\">&gt;</span><span data-k=\"punct\">;</span></span></span></code></pre></figure><p>Taken together, the mechanisms of elision and inference for lifetimes let us implement the vast majority of low level ownership patterns <em>without</em> having to specify lifetimes to the compiler explicitly (yay).\nIt should also be noted that one consequence of this body-derived inference is that a body change can change an inferred public signature, but that is just the tradeoff here.</p>\n<h2 id=\"suspension\">Suspension</h2><p>As discussed in <a href=\"/docs/language/expressions/#continuations\">Continuations</a>, values and objects in &quot;managed land&quot; work exactly like in regular TypeScript and can be referenced and mutated freely wherever.\nWhen <em>borrowing</em> across suspension points (like <code>yield</code> or <code>await</code>), the compiler must still guarantee that the core safety rules are upheld.\nAnd because multiple continuations may be active concurrently (even if not in parallel), borrows that must be owned by the current frame to cross suspension points - in other words, borrows coming from managed values must <em>not</em> cross suspension points.</p>\n<p>It follows that the same body is fine or rejected purely based on where the borrowed value lives:</p>\n<figure class=\"markdown-code\"><figcaption><span class=\"markdown-code__title\">Suspension</span><span class=\"markdown-code__format\">.ds</span></figcaption><pre tabindex=\"0\"><code class=\"markdown-code-lines\"><span class=\"markdown-code-line\"><span class=\"markdown-code-gutter\">1</span><span class=\"markdown-code-text\"><span data-k=\"comment\">// owned by the frame: the borrow may cross suspension</span></span></span><span class=\"markdown-code-line\"><span class=\"markdown-code-gutter\">2</span><span class=\"markdown-code-text\"><span data-k=\"keyword\">async</span> <span data-k=\"keyword\">function</span> <span data-k=\"function\">readOwned</span><span data-k=\"punct\">(</span><span data-k=\"name\">user</span><span data-k=\"punct\">:</span> <span data-k=\"punct\">^</span><span data-k=\"type\">User</span><span data-k=\"punct\">)</span><span data-k=\"punct\">:</span> <span data-k=\"type\">Promise</span><span data-k=\"punct\">&lt;</span><span data-k=\"type\">string</span><span data-k=\"punct\">&gt;</span> <span data-k=\"punct\">{</span></span></span><span class=\"markdown-code-line\"><span class=\"markdown-code-gutter\">3</span><span class=\"markdown-code-text\">    <span data-k=\"keyword\">const</span> <span data-k=\"name\">name</span> <span data-k=\"punct\">=</span> <span data-k=\"punct\">&amp;</span><span data-k=\"keyword\">readonly</span> <span data-k=\"name\">user</span><span data-k=\"punct\">.</span><span data-k=\"property\">name</span><span data-k=\"punct\">;</span></span></span><span class=\"markdown-code-line\"><span class=\"markdown-code-gutter\">4</span><span class=\"markdown-code-text\">    <span data-k=\"keyword\">await</span> <span data-k=\"function\">tick</span><span data-k=\"punct\">(</span><span data-k=\"punct\">)</span><span data-k=\"punct\">;</span></span></span><span class=\"markdown-code-line\"><span class=\"markdown-code-gutter\">5</span><span class=\"markdown-code-text\">    <span data-k=\"keyword\">return</span> <span data-k=\"name\">name</span><span data-k=\"punct\">.</span><span data-k=\"property\">clone</span><span data-k=\"punct\">(</span><span data-k=\"punct\">)</span><span data-k=\"punct\">;</span></span></span><span class=\"markdown-code-line\"><span class=\"markdown-code-gutter\">6</span><span class=\"markdown-code-text\"><span data-k=\"punct\">}</span></span></span><span class=\"markdown-code-line\"><span class=\"markdown-code-gutter\">7</span><span class=\"markdown-code-text\"> </span></span><span class=\"markdown-code-line\"><span class=\"markdown-code-gutter\">8</span><span class=\"markdown-code-text\"><span data-k=\"comment\">// borrowed parameter: also fine, the caller proves the source is owned or static</span></span></span><span class=\"markdown-code-line\"><span class=\"markdown-code-gutter\">9</span><span class=\"markdown-code-text\"><span data-k=\"keyword\">async</span> <span data-k=\"keyword\">function</span> <span data-k=\"function\">readBorrowed</span><span data-k=\"punct\">(</span><span data-k=\"name\">user</span><span data-k=\"punct\">:</span> <span data-k=\"punct\">&amp;</span><span data-k=\"type\">User</span><span data-k=\"punct\">)</span><span data-k=\"punct\">:</span> <span data-k=\"type\">Promise</span><span data-k=\"punct\">&lt;</span><span data-k=\"type\">string</span><span data-k=\"punct\">&gt;</span> <span data-k=\"punct\">{</span></span></span><span class=\"markdown-code-line\"><span class=\"markdown-code-gutter\">10</span><span class=\"markdown-code-text\">    <span data-k=\"keyword\">const</span> <span data-k=\"name\">name</span> <span data-k=\"punct\">=</span> <span data-k=\"punct\">&amp;</span><span data-k=\"keyword\">readonly</span> <span data-k=\"name\">user</span><span data-k=\"punct\">.</span><span data-k=\"property\">name</span><span data-k=\"punct\">;</span></span></span><span class=\"markdown-code-line\"><span class=\"markdown-code-gutter\">11</span><span class=\"markdown-code-text\">    <span data-k=\"keyword\">await</span> <span data-k=\"function\">tick</span><span data-k=\"punct\">(</span><span data-k=\"punct\">)</span><span data-k=\"punct\">;</span></span></span><span class=\"markdown-code-line\"><span class=\"markdown-code-gutter\">12</span><span class=\"markdown-code-text\">    <span data-k=\"keyword\">return</span> <span data-k=\"name\">name</span><span data-k=\"punct\">.</span><span data-k=\"property\">clone</span><span data-k=\"punct\">(</span><span data-k=\"punct\">)</span><span data-k=\"punct\">;</span></span></span><span class=\"markdown-code-line\"><span class=\"markdown-code-gutter\">13</span><span class=\"markdown-code-text\"><span data-k=\"punct\">}</span></span></span><span class=\"markdown-code-line\"><span class=\"markdown-code-gutter\">14</span><span class=\"markdown-code-text\"> </span></span><span class=\"markdown-code-line\"><span class=\"markdown-code-gutter\">15</span><span class=\"markdown-code-text\"><span data-k=\"comment\">// managed: rejected, another continuation could touch `user` while we are parked</span></span></span><span class=\"markdown-code-line\"><span class=\"markdown-code-gutter\">16</span><span class=\"markdown-code-text\"><span data-k=\"keyword\">async</span> <span data-k=\"keyword\">function</span> <span data-k=\"function\">readManaged</span><span data-k=\"punct\">(</span><span data-k=\"name\">user</span><span data-k=\"punct\">:</span> <span data-k=\"type\">User</span><span data-k=\"punct\">)</span><span data-k=\"punct\">:</span> <span data-k=\"type\">Promise</span><span data-k=\"punct\">&lt;</span><span data-k=\"type\">string</span><span data-k=\"punct\">&gt;</span> <span data-k=\"punct\">{</span></span></span><span class=\"markdown-code-line\"><span class=\"markdown-code-gutter\">17</span><span class=\"markdown-code-text\">    <span data-k=\"keyword\">const</span> <span data-k=\"name\">name</span> <span data-k=\"punct\">=</span> <span data-k=\"punct\">&amp;</span><span data-k=\"keyword\">readonly</span> <span data-k=\"name\">user</span><span data-k=\"punct\">.</span><span data-k=\"property\">name</span><span data-k=\"punct\">;</span></span></span><span class=\"markdown-code-line\"><span class=\"markdown-code-gutter\">18</span><span class=\"markdown-code-text\">    <span data-k=\"keyword\">await</span> <span data-k=\"function\">tick</span><span data-k=\"punct\">(</span><span data-k=\"punct\">)</span><span data-k=\"punct\">;</span> <span data-k=\"comment\">// ERROR: `name` borrows managed storage across suspension</span></span></span><span class=\"markdown-code-line\"><span class=\"markdown-code-gutter\">19</span><span class=\"markdown-code-text\">    <span data-k=\"keyword\">return</span> <span data-k=\"name\">name</span><span data-k=\"punct\">.</span><span data-k=\"property\">clone</span><span data-k=\"punct\">(</span><span data-k=\"punct\">)</span><span data-k=\"punct\">;</span></span></span><span class=\"markdown-code-line\"><span class=\"markdown-code-gutter\">20</span><span class=\"markdown-code-text\"><span data-k=\"punct\">}</span></span></span></code></pre></figure><p>One load-bearing guarantee underneath all of this: suspension points are always lexically explicit (<code>await</code> and <code>yield</code>).\nThere is no hidden suspension - no implicit awaits, no preemption points, no suspending allocators - so &quot;does this borrow cross suspension&quot; can always be answered by looking at the code (and declaration-only APIs need no extra annotations, since asyncness is visible in signatures and <code>declare</code> signatures already spell out lifetimes).</p>\n<h2 id=\"drop\">Drop</h2><p>Whenever the lifetime of a value ends and it is deallocated, Destack supports running a <code>Drop</code> finalizer, similar to Rust&#39;s <code>Drop</code>.\nThis happens when the compiler inserts a drop for an owned local after its last use, when an owned field is being destroyed, and when the runtime <em>eventually</em> reclaims an unreachable managed allocation.\nDrop sites are statically known: maybe-present state must be represented as an explicit type like <code>T | undefined</code>, and a place conditionally moved on one branch is an error at the join, so there are no runtime drop flags as such.</p>\n<figure class=\"markdown-code\"><figcaption><span class=\"markdown-code__title\">Drop</span><span class=\"markdown-code__format\">.ds</span></figcaption><pre tabindex=\"0\"><code class=\"markdown-code-lines\"><span class=\"markdown-code-line\"><span class=\"markdown-code-gutter\">1</span><span class=\"markdown-code-text\"><span data-k=\"keyword\">function</span> <span data-k=\"function\">run</span><span data-k=\"punct\">(</span><span data-k=\"punct\">)</span><span data-k=\"punct\">:</span> <span data-k=\"type\">void</span> <span data-k=\"punct\">{</span></span></span><span class=\"markdown-code-line\"><span class=\"markdown-code-gutter\">2</span><span class=\"markdown-code-text\">    <span data-k=\"keyword\">let</span> <span data-k=\"name\">buffer</span><span data-k=\"punct\">:</span> <span data-k=\"punct\">^</span><span data-k=\"type\">Buffer</span> <span data-k=\"punct\">=</span> <span data-k=\"type\">Buffer</span><span data-k=\"punct\">.</span><span data-k=\"property\">open</span><span data-k=\"punct\">(</span><span data-k=\"punct\">)</span><span data-k=\"punct\">;</span></span></span><span class=\"markdown-code-line\"><span class=\"markdown-code-gutter\">3</span><span class=\"markdown-code-text\">    <span data-k=\"function\">process</span><span data-k=\"punct\">(</span><span data-k=\"punct\">&amp;</span><span data-k=\"name\">buffer</span><span data-k=\"punct\">)</span><span data-k=\"punct\">;</span></span></span><span class=\"markdown-code-line\"><span class=\"markdown-code-gutter\">4</span><span class=\"markdown-code-text\">    <span data-k=\"comment\">// `buffer` is dropped immediately after its last use</span></span></span><span class=\"markdown-code-line\"><span class=\"markdown-code-gutter\">5</span><span class=\"markdown-code-text\"><span data-k=\"punct\">}</span></span></span></code></pre></figure><p>The same <code>Drop</code> also works for managed references, where it is run before they are freed:</p>\n<figure class=\"markdown-code\"><figcaption><span class=\"markdown-code__title\">Drop</span><span class=\"markdown-code__format\">.ds</span></figcaption><pre tabindex=\"0\"><code class=\"markdown-code-lines\"><span class=\"markdown-code-line\"><span class=\"markdown-code-gutter\">1</span><span class=\"markdown-code-text\"><span data-k=\"keyword\">class</span> <span data-k=\"type\">Image</span> <span data-k=\"punct\">{</span></span></span><span class=\"markdown-code-line\"><span class=\"markdown-code-gutter\">2</span><span class=\"markdown-code-text\">    <span data-k=\"property\">pixels</span><span data-k=\"punct\">:</span> <span data-k=\"type\">Unique</span><span data-k=\"punct\">&lt;</span><span data-k=\"punct\">[</span><span data-k=\"type\">uint8</span><span data-k=\"punct\">]</span><span data-k=\"punct\">&gt;</span><span data-k=\"punct\">;</span></span></span><span class=\"markdown-code-line\"><span class=\"markdown-code-gutter\">3</span><span class=\"markdown-code-text\"><span data-k=\"punct\">}</span></span></span><span class=\"markdown-code-line\"><span class=\"markdown-code-gutter\">4</span><span class=\"markdown-code-text\"> </span></span><span class=\"markdown-code-line\"><span class=\"markdown-code-gutter\">5</span><span class=\"markdown-code-text\"><span data-k=\"keyword\">let</span> <span data-k=\"name\">image</span><span data-k=\"punct\">:</span> <span data-k=\"type\">Image</span> <span data-k=\"punct\">=</span> <span data-k=\"keyword\">new</span> <span data-k=\"type\">Image</span><span data-k=\"punct\">(</span><span data-k=\"punct\">)</span><span data-k=\"punct\">;</span></span></span><span class=\"markdown-code-line\"><span class=\"markdown-code-gutter\">6</span><span class=\"markdown-code-text\"><span data-k=\"comment\">// when `image` is collected, the GC runs drop glue for `pixels`</span></span></span></code></pre></figure><p>Unlike Rust and C++ RAII, Destack models <code>Drop</code> and <code>Dispose</code> / <code>AsyncDispose</code> separately: <code>Drop</code> follows lifetime, while <a href=\"/docs/language/expressions/#using\"><code>using</code></a> is lexical.\nBecause of this split, <code>Drop</code> <em>can</em> run eagerly after last use, which is great for memory pressure, but also means Destack&#39;s <code>Drop</code> is not the right fit for lexical RAII-style cleanup.\nIn general, <code>Drop</code> should manage memory and memory-shaped cleanup, while <code>using</code> should manage richer resource finalization:</p>\n<div class=\"markdown-table\" tabindex=\"0\"><table><thead><tr>\n<th>Protocol</th>\n<th>Purpose</th>\n<th>Timing</th>\n</tr>\n</thead><tbody><tr>\n<td><code>Drop</code></td>\n<td>ownership finalization for memory and owned fields</td>\n<td>deterministic for owned values, GC-timed for managed values</td>\n</tr>\n<tr>\n<td><code>Dispose</code></td>\n<td>explicit synchronous resource cleanup</td>\n<td>lexical <code>using</code> scope exit</td>\n</tr>\n<tr>\n<td><code>AsyncDispose</code></td>\n<td>explicit asynchronous resource cleanup</td>\n<td>lexical <code>await using</code> scope exit</td>\n</tr>\n</tbody></table></div><p>External resources such as files, locks, sockets, transactions, and temporary runtime registrations should use <code>Dispose</code> or <code>AsyncDispose</code>, not <code>Drop</code>.\nThis keeps RAII-style cleanup explicit and predictable even though ordinary TS++ values are &quot;managed&quot; by default:</p>\n<figure class=\"markdown-code\"><figcaption><span class=\"markdown-code__title\">Drop</span><span class=\"markdown-code__format\">.ds</span></figcaption><pre tabindex=\"0\"><code class=\"markdown-code-lines\"><span class=\"markdown-code-line\"><span class=\"markdown-code-gutter\">1</span><span class=\"markdown-code-text\"><span data-k=\"keyword\">using</span> <span data-k=\"name\">file</span> <span data-k=\"punct\">=</span> <span data-k=\"type\">File</span><span data-k=\"punct\">.</span><span data-k=\"property\">open</span><span data-k=\"punct\">(</span><span data-k=\"name\">path</span><span data-k=\"punct\">)</span><span data-k=\"punct\">?</span><span data-k=\"punct\">;</span></span></span><span class=\"markdown-code-line\"><span class=\"markdown-code-gutter\">2</span><span class=\"markdown-code-text\"><span data-k=\"keyword\">await</span> <span data-k=\"keyword\">using</span> <span data-k=\"name\">connection</span> <span data-k=\"punct\">=</span> <span data-k=\"keyword\">await</span> <span data-k=\"name\">pool</span><span data-k=\"punct\">.</span><span data-k=\"property\">connect</span><span data-k=\"punct\">(</span><span data-k=\"punct\">)</span><span data-k=\"punct\">;</span></span></span></code></pre></figure><p>Low-level code can of course still control finalization explicitly:\n<code>drop(value)</code> ends ownership immediately, <code>forget(value)</code> intentionally suppresses automatic drop, <code>ManuallyDrop&lt;T&gt;</code> stores a value outside automatic drop handling, and <code>Box&lt;T&gt;.leak()</code> turns one owned allocation into a static borrow.</p>\n<h2 id=\"allocation\">Allocation</h2><p>The primary way to construct new values is <code>new</code>, which initializes a <code>T</code> and produces the ownership form required by the <em>destination</em> type - <code>new</code> is really just an initializer that calls the type&#39;s constructor.\nThe required destination type decides whether that is managed storage, owned storage, inline frame storage, shared storage, or some lower-level allocation form.</p>\n<figure class=\"markdown-code\"><figcaption><span class=\"markdown-code__title\">Allocation</span><span class=\"markdown-code__format\">.ds</span></figcaption><pre tabindex=\"0\"><code class=\"markdown-code-lines\"><span class=\"markdown-code-line\"><span class=\"markdown-code-gutter\">1</span><span class=\"markdown-code-text\"><span data-k=\"keyword\">let</span> <span data-k=\"name\">a</span><span data-k=\"punct\">:</span> <span data-k=\"type\">User</span> <span data-k=\"punct\">=</span> <span data-k=\"keyword\">new</span> <span data-k=\"type\">User</span><span data-k=\"punct\">(</span><span data-k=\"punct\">)</span><span data-k=\"punct\">;</span>   <span data-k=\"comment\">// managed</span></span></span><span class=\"markdown-code-line\"><span class=\"markdown-code-gutter\">2</span><span class=\"markdown-code-text\"><span data-k=\"keyword\">let</span> <span data-k=\"name\">b</span><span data-k=\"punct\">:</span> <span data-k=\"punct\">^</span><span data-k=\"type\">User</span> <span data-k=\"punct\">=</span> <span data-k=\"keyword\">new</span> <span data-k=\"type\">User</span><span data-k=\"punct\">(</span><span data-k=\"punct\">)</span><span data-k=\"punct\">;</span>  <span data-k=\"comment\">// owned</span></span></span></code></pre></figure><p>In some situations it is useful to handle allocation errors directly, and for that Destack supports more direct fallible allocation accessors both via higher level <code>try*</code> methods in standard library types (like <code>Array.tryReserve</code>) and the low level intrinsics (<code>MaybeUninit&lt;T&gt;</code>, <code>Unique&lt;T&gt;</code>, etc.) that they are built on.\nRegular managed object allocation (<code>new T()</code>) can also be made fallible via the <code>new?</code> operator, which behaves similar in spirit to the regular <a href=\"/docs/language/expressions/#maybe-must-and-coalesce\"><code>?</code></a> and <code>await?</code> operators, propagating an <code>AllocationError</code> to the containing context:</p>\n<figure class=\"markdown-code\"><figcaption><span class=\"markdown-code__title\">Allocation</span><span class=\"markdown-code__format\">.ds</span></figcaption><pre tabindex=\"0\"><code class=\"markdown-code-lines\"><span class=\"markdown-code-line\"><span class=\"markdown-code-gutter\">1</span><span class=\"markdown-code-text\"><span data-k=\"keyword\">try</span> <span data-k=\"punct\">{</span></span></span><span class=\"markdown-code-line\"><span class=\"markdown-code-gutter\">2</span><span class=\"markdown-code-text\">    <span data-k=\"keyword\">let</span> <span data-k=\"name\">buffer</span><span data-k=\"punct\">:</span> <span data-k=\"type\">Block</span><span data-k=\"punct\">[</span><span data-k=\"punct\">]</span> <span data-k=\"punct\">=</span> <span data-k=\"type\">Array</span><span data-k=\"punct\">.</span><span data-k=\"property\">tryWithCapacity</span><span data-k=\"punct\">(</span><span data-k=\"name\">count</span><span data-k=\"punct\">)</span><span data-k=\"punct\">?</span><span data-k=\"punct\">;</span> <span data-k=\"comment\">// fallible library allocation</span></span></span><span class=\"markdown-code-line\"><span class=\"markdown-code-gutter\">3</span><span class=\"markdown-code-text\">    <span data-k=\"keyword\">let</span> <span data-k=\"name\">page</span> <span data-k=\"punct\">=</span> <span data-k=\"keyword\">new</span><span data-k=\"punct\">?</span> <span data-k=\"type\">Page</span><span data-k=\"punct\">(</span><span data-k=\"name\">buffer</span><span data-k=\"punct\">)</span><span data-k=\"punct\">;</span>                        <span data-k=\"comment\">// fallible managed allocation</span></span></span><span class=\"markdown-code-line\"><span class=\"markdown-code-gutter\">4</span><span class=\"markdown-code-text\">    <span data-k=\"name\">page</span><span data-k=\"punct\">.</span><span data-k=\"property\">fill</span><span data-k=\"punct\">(</span><span data-k=\"punct\">)</span><span data-k=\"punct\">?</span><span data-k=\"punct\">;</span></span></span><span class=\"markdown-code-line\"><span class=\"markdown-code-gutter\">5</span><span class=\"markdown-code-text\"> </span></span><span class=\"markdown-code-line\"><span class=\"markdown-code-gutter\">6</span><span class=\"markdown-code-text\">    <span data-k=\"keyword\">return</span> <span data-k=\"name\">page</span><span data-k=\"punct\">;</span></span></span><span class=\"markdown-code-line\"><span class=\"markdown-code-gutter\">7</span><span class=\"markdown-code-text\"><span data-k=\"punct\">}</span> <span data-k=\"keyword\">catch</span> <span data-k=\"punct\">(</span><span data-k=\"name\">e</span><span data-k=\"punct\">:</span> <span data-k=\"type\">AllocationError</span><span data-k=\"punct\">)</span> <span data-k=\"punct\">{</span></span></span><span class=\"markdown-code-line\"><span class=\"markdown-code-gutter\">8</span><span class=\"markdown-code-text\">    <span data-k=\"keyword\">return</span> <span data-k=\"literal\">null</span><span data-k=\"punct\">;</span></span></span><span class=\"markdown-code-line\"><span class=\"markdown-code-gutter\">9</span><span class=\"markdown-code-text\"><span data-k=\"punct\">}</span></span></span></code></pre></figure><p>Code can also opt out of managed allocation locally via <a href=\"/docs/language/expressions/#restrictions\">restrictions</a>:</p>\n<figure class=\"markdown-code\"><figcaption><span class=\"markdown-code__title\">Allocation</span><span class=\"markdown-code__format\">.ds</span></figcaption><pre tabindex=\"0\"><code class=\"markdown-code-lines\"><span class=\"markdown-code-line\"><span class=\"markdown-code-gutter\">1</span><span class=\"markdown-code-text\">@<span data-k=\"name\">noManaged</span></span></span><span class=\"markdown-code-line\"><span class=\"markdown-code-gutter\">2</span><span class=\"markdown-code-text\"><span data-k=\"keyword\">function</span> <span data-k=\"function\">processFrame</span><span data-k=\"punct\">(</span><span data-k=\"name\">input</span><span data-k=\"punct\">:</span> <span data-k=\"punct\">&amp;</span><span data-k=\"punct\">[</span><span data-k=\"type\">Sample</span><span data-k=\"punct\">]</span><span data-k=\"punct\">)</span><span data-k=\"punct\">:</span> <span data-k=\"punct\">^</span><span data-k=\"type\">Frame</span> <span data-k=\"punct\">{</span></span></span><span class=\"markdown-code-line\"><span class=\"markdown-code-gutter\">3</span><span class=\"markdown-code-text\">    <span data-k=\"keyword\">return</span> <span data-k=\"function\">buildFrame</span><span data-k=\"punct\">(</span><span data-k=\"name\">input</span><span data-k=\"punct\">)</span><span data-k=\"punct\">;</span></span></span><span class=\"markdown-code-line\"><span class=\"markdown-code-gutter\">4</span><span class=\"markdown-code-text\"><span data-k=\"punct\">}</span></span></span><span class=\"markdown-code-line\"><span class=\"markdown-code-gutter\">5</span><span class=\"markdown-code-text\"> </span></span><span class=\"markdown-code-line\"><span class=\"markdown-code-gutter\">6</span><span class=\"markdown-code-text\">@<span data-k=\"name\">noHeap</span></span></span><span class=\"markdown-code-line\"><span class=\"markdown-code-gutter\">7</span><span class=\"markdown-code-text\"><span data-k=\"keyword\">function</span> <span data-k=\"function\">interruptHandler</span><span data-k=\"punct\">(</span><span data-k=\"name\">input</span><span data-k=\"punct\">:</span> <span data-k=\"punct\">&amp;</span><span data-k=\"punct\">[</span><span data-k=\"type\">Sample</span><span data-k=\"punct\">]</span><span data-k=\"punct\">)</span><span data-k=\"punct\">:</span> <span data-k=\"type\">Frame</span> <span data-k=\"punct\">{</span></span></span><span class=\"markdown-code-line\"><span class=\"markdown-code-gutter\">8</span><span class=\"markdown-code-text\">    <span data-k=\"keyword\">return</span> <span data-k=\"function\">buildFrameOnStack</span><span data-k=\"punct\">(</span><span data-k=\"name\">input</span><span data-k=\"punct\">)</span><span data-k=\"punct\">;</span></span></span><span class=\"markdown-code-line\"><span class=\"markdown-code-gutter\">9</span><span class=\"markdown-code-text\"><span data-k=\"punct\">}</span></span></span></code></pre></figure><h2 id=\"space\">Space</h2><p>The space of a value determines where it is actually located in memory, and since Destack follows web and TypeScript conventions, the <code>Worker</code>-<em>local</em> heap is the default main memory space.\nOrdinary managed objects, arrays, strings, functions, closures, and module bindings live in local space, and user and library code can almost always just pretend spaces don&#39;t even exist.</p>\n<figure class=\"markdown-code\"><figcaption><span class=\"markdown-code__title\">Space</span><span class=\"markdown-code__format\">.ds</span></figcaption><pre tabindex=\"0\"><code class=\"markdown-code-lines\"><span class=\"markdown-code-line\"><span class=\"markdown-code-gutter\">1</span><span class=\"markdown-code-text\"><span data-k=\"keyword\">struct</span> <span data-k=\"type\">Request</span><span data-k=\"punct\">&lt;</span><span data-k=\"type\">T</span><span data-k=\"punct\">&gt;</span> <span data-k=\"punct\">{</span></span></span><span class=\"markdown-code-line\"><span class=\"markdown-code-gutter\">2</span><span class=\"markdown-code-text\">    <span data-k=\"property\">header</span><span data-k=\"punct\">:</span> <span data-k=\"type\">Header</span><span data-k=\"punct\">;</span></span></span><span class=\"markdown-code-line\"><span class=\"markdown-code-gutter\">3</span><span class=\"markdown-code-text\">    <span data-k=\"property\">body</span><span data-k=\"punct\">:</span> <span data-k=\"type\">T</span><span data-k=\"punct\">;</span></span></span><span class=\"markdown-code-line\"><span class=\"markdown-code-gutter\">4</span><span class=\"markdown-code-text\"><span data-k=\"punct\">}</span></span></span><span class=\"markdown-code-line\"><span class=\"markdown-code-gutter\">5</span><span class=\"markdown-code-text\"> </span></span><span class=\"markdown-code-line\"><span class=\"markdown-code-gutter\">6</span><span class=\"markdown-code-text\"><span data-k=\"keyword\">let</span> <span data-k=\"name\">localRequest</span><span data-k=\"punct\">:</span> <span data-k=\"type\">Request</span><span data-k=\"punct\">&lt;</span><span data-k=\"type\">Body</span><span data-k=\"punct\">&gt;</span><span data-k=\"punct\">;</span>          <span data-k=\"comment\">// ambient, default -&gt; Request is local heap</span></span></span><span class=\"markdown-code-line\"><span class=\"markdown-code-gutter\">7</span><span class=\"markdown-code-text\"><span data-k=\"keyword\">let</span> <span data-k=\"name\">sharedRequest</span><span data-k=\"punct\">:</span> shared <span data-k=\"type\">Request</span><span data-k=\"punct\">&lt;</span><span data-k=\"type\">Body</span><span data-k=\"punct\">&gt;</span><span data-k=\"punct\">;</span>  <span data-k=\"comment\">// explicit, shared -&gt; Request is shared heap</span></span></span></code></pre></figure><p>In general, type placement is contextual: all types are &quot;ambient&quot; by default, i.e., they come with no inherent placement, and types are only placed wherever their parent is placed until someone either specifies placement explicitly (e.g., <code>local T</code>, <code>shared T</code>) or we reach the module top (whcih is &quot;local&quot;).\nSpecific nominal declarations may also choose an intrinsic placement for themselves, which then forces them into a specific space:</p>\n<figure class=\"markdown-code\"><figcaption><span class=\"markdown-code__title\">Space</span><span class=\"markdown-code__format\">.ds</span></figcaption><pre tabindex=\"0\"><code class=\"markdown-code-lines\"><span class=\"markdown-code-line\"><span class=\"markdown-code-gutter\">1</span><span class=\"markdown-code-text\">local <span data-k=\"keyword\">newtype</span> <span data-k=\"keyword\">interface</span> <span data-k=\"type\">Awaitable</span><span data-k=\"punct\">&lt;</span><span data-k=\"type\">T</span><span data-k=\"punct\">&gt;</span> <span data-k=\"punct\">{</span> <span data-k=\"property\">await</span><span data-k=\"punct\">(</span><span data-k=\"punct\">)</span><span data-k=\"punct\">:</span> <span data-k=\"type\">T</span> <span data-k=\"punct\">}</span></span></span><span class=\"markdown-code-line\"><span class=\"markdown-code-gutter\">2</span><span class=\"markdown-code-text\">local <span data-k=\"keyword\">class</span> <span data-k=\"type\">Promise</span><span data-k=\"punct\">&lt;</span><span data-k=\"type\">T</span><span data-k=\"punct\">&gt;</span> <span data-k=\"punct\">{</span><span data-k=\"punct\">}</span></span></span><span class=\"markdown-code-line\"><span class=\"markdown-code-gutter\">3</span><span class=\"markdown-code-text\">shared <span data-k=\"keyword\">class</span> <span data-k=\"type\">Channel</span><span data-k=\"punct\">&lt;</span><span data-k=\"type\">T</span><span data-k=\"punct\">&gt;</span> <span data-k=\"punct\">{</span><span data-k=\"punct\">}</span></span></span><span class=\"markdown-code-line\"><span class=\"markdown-code-gutter\">4</span><span class=\"markdown-code-text\">local <span data-k=\"keyword\">newtype</span> <span data-k=\"type\">TaskId</span> <span data-k=\"punct\">=</span> <span data-k=\"type\">uint64</span><span data-k=\"punct\">;</span></span></span><span class=\"markdown-code-line\"><span class=\"markdown-code-gutter\">5</span><span class=\"markdown-code-text\"> </span></span><span class=\"markdown-code-line\"><span class=\"markdown-code-gutter\">6</span><span class=\"markdown-code-text\"><span data-k=\"type\">PlaceOf</span><span data-k=\"punct\">&lt;</span><span data-k=\"type\">Promise</span><span data-k=\"punct\">&lt;</span><span data-k=\"type\">void</span><span data-k=\"punct\">&gt;</span><span data-k=\"punct\">&gt;</span> <span data-k=\"keyword\">satisfies</span> <span data-k=\"string\">&quot;local&quot;</span><span data-k=\"punct\">;</span></span></span><span class=\"markdown-code-line\"><span class=\"markdown-code-gutter\">7</span><span class=\"markdown-code-text\"><span data-k=\"type\">PlaceOf</span><span data-k=\"punct\">&lt;</span><span data-k=\"type\">Channel</span><span data-k=\"punct\">&lt;</span><span data-k=\"type\">string</span><span data-k=\"punct\">&gt;</span><span data-k=\"punct\">&gt;</span> <span data-k=\"keyword\">satisfies</span> <span data-k=\"string\">&quot;shared&quot;</span><span data-k=\"punct\">;</span></span></span><span class=\"markdown-code-line\"><span class=\"markdown-code-gutter\">8</span><span class=\"markdown-code-text\"><span data-k=\"type\">PlaceOf</span><span data-k=\"punct\">&lt;</span><span data-k=\"type\">TaskId</span><span data-k=\"punct\">&gt;</span> <span data-k=\"keyword\">satisfies</span> <span data-k=\"string\">&quot;local&quot;</span><span data-k=\"punct\">;</span></span></span></code></pre></figure><h3 id=\"shared-space\">Shared Space</h3><p>In TypeScript tradition, each &quot;Worker&quot; (in the JS spec generally referred to as &quot;Agent&quot;) has its own isolated local heap that cannot be touched by other workers.\nFor sharing memory across workers, TypeScript has the <code>SharedArrayBuffer</code> concept and plain old message passing with <code>postMessage</code>.\nThat works, but is architecturally limited and makes it complex to implement more sophisticated parallelism patterns.</p>\n<p>Destack supports an explicit, separate, fully featured <em>shared</em> memory space that is visible to all <code>Worker</code>s in the same <code>Runtime</code> via regular references and objects.\nBasically, <code>shared T</code> is the typed, generalized version of the <code>SharedArrayBuffer</code> idea with the full type system and object graphs at our disposal with the simple rule that local may point into shared, but shared must not point into local memory.</p>\n<p>It&#39;s important to note that <em>by itself</em> shared placement, like any space placement, is <strong>not</strong> a synchronization primitive and does <strong>not</strong> imply atomic access, locking, <code>Sync</code>, or anything like that.\nThat is by design; it&#39;s up to userland libraries to require <a href=\"#capabilities\">capabilities</a> like <code>Send</code> and <code>Sync</code> for APIs that transfer or publish values for correctness, but <code>shared</code> itself is really only about placement.</p>\n<h3 id=\"static-space\">Static Space</h3><p>Because Destack inherits the JS/TS Worker model for isolation, module-scoped constants are owned by each <em>Worker</em> and are not actually process-global as they would be in most other languages.\nFor genuinely <em>shared</em> process-global state, the binding <em>itself</em> can be declared as <code>shared</code>.</p>\n<div class=\"markdown-table\" tabindex=\"0\"><table><thead><tr>\n<th>Form</th>\n<th>Binding place</th>\n<th>Value place</th>\n<th>Meaning</th>\n</tr>\n</thead><tbody><tr>\n<td><code>const world = new World()</code></td>\n<td>local</td>\n<td>local</td>\n<td>one local module binding and one local value</td>\n</tr>\n<tr>\n<td><code>const world: shared World = new World()</code></td>\n<td>local</td>\n<td>shared</td>\n<td>one local binding cell holding one shared handle</td>\n</tr>\n<tr>\n<td><code>shared const world: World = new World()</code></td>\n<td>shared</td>\n<td>shared</td>\n<td>one shared binding cell initialized in shared space</td>\n</tr>\n<tr>\n<td><code>shared const world: shared World = new World()</code></td>\n<td>shared</td>\n<td>shared</td>\n<td>same runtime meaning, explicit on both axes</td>\n</tr>\n</tbody></table></div><p>Note that marking the binding itself as <code>shared</code> also types the value as <code>shared</code> (as it is illegal to point from shared storage into local storage anyway, this is convenient).\nShared bindings are always <code>const</code>, and <code>const</code> means exactly what it means in TypeScript: the binding is not reassignable, while the value behind it mutates freely through its own API.</p>\n<p>One constraint follows directly from the Worker model: a <code>shared</code> binding is reachable from <em>every</em> Worker by construction, so it must meet the same bar as any value crossing Workers - the value type must be <code>Sync</code> (see <a href=\"#capabilities\">Capabilities</a>).\nIn particular, a bare owned global like <code>shared const world: ^World</code> is rejected: every Worker can reach the binding, so its exclusivity cannot be checked.\nGlobal mutable state instead puts a lock in the static and lets the guard be the runtime exclusivity oracle:</p>\n<figure class=\"markdown-code\"><figcaption><span class=\"markdown-code__title\">Static Space</span><span class=\"markdown-code__format\">.ds</span></figcaption><pre tabindex=\"0\"><code class=\"markdown-code-lines\"><span class=\"markdown-code-line\"><span class=\"markdown-code-gutter\">1</span><span class=\"markdown-code-text\">shared <span data-k=\"keyword\">const</span> <span data-k=\"name\">world</span><span data-k=\"punct\">:</span> <span data-k=\"type\">Mutex</span><span data-k=\"punct\">&lt;</span><span data-k=\"type\">World</span><span data-k=\"punct\">&gt;</span> <span data-k=\"punct\">=</span> <span data-k=\"keyword\">new</span> <span data-k=\"type\">Mutex</span><span data-k=\"punct\">(</span><span data-k=\"keyword\">new</span> <span data-k=\"type\">World</span><span data-k=\"punct\">(</span><span data-k=\"punct\">)</span><span data-k=\"punct\">)</span><span data-k=\"punct\">;</span></span></span><span class=\"markdown-code-line\"><span class=\"markdown-code-gutter\">2</span><span class=\"markdown-code-text\"> </span></span><span class=\"markdown-code-line\"><span class=\"markdown-code-gutter\">3</span><span class=\"markdown-code-text\"><span data-k=\"keyword\">const</span> <span data-k=\"name\">view</span> <span data-k=\"punct\">=</span> <span data-k=\"name\">world</span><span data-k=\"punct\">.</span><span data-k=\"property\">lock</span><span data-k=\"punct\">(</span><span data-k=\"punct\">)</span><span data-k=\"punct\">;</span> <span data-k=\"comment\">// guard dereferences to &amp;exclusive World</span></span></span></code></pre></figure><p>Because module code runs on every Worker, shared bindings are initialized exactly once by the runtime, before any other Worker can observe them.</p>\n<h2 id=\"conversions\">Conversions</h2><p>Reference conversions follow directly from <a href=\"#memory\">the four memory rules</a>, and borrowing from a live place works whenever the requested loan rules hold:</p>\n<div class=\"markdown-table\" tabindex=\"0\"><table><thead><tr>\n<th>Source</th>\n<th>Borrow</th>\n<th>Notes</th>\n</tr>\n</thead><tbody><tr>\n<td>local managed <code>T</code></td>\n<td><code>&amp;T</code> / <code>&amp;readonly T</code> / <code>&amp;exclusive T</code></td>\n<td>exclusive needs no overlapping loan; none may cross <a href=\"#suspension\">suspension</a></td>\n</tr>\n<tr>\n<td>owned <code>^T</code></td>\n<td><code>&amp;T</code> / <code>&amp;readonly T</code> / <code>&amp;exclusive T</code></td>\n<td>owned sources may also cross suspension</td>\n</tr>\n<tr>\n<td>shared owned <code>shared ^T</code></td>\n<td><code>shared &amp;T</code> / <code>shared &amp;readonly T</code> / <code>shared &amp;exclusive T</code></td>\n<td>owned storage stays unique even in shared space, since the handle itself still has one holder</td>\n</tr>\n<tr>\n<td>shared managed <code>T</code></td>\n<td><code>&amp;T</code> / <code>&amp;readonly T</code></td>\n<td>mutation routes through <code>Sync</code> APIs and atomic field access (see <a href=\"#synchronization\">Synchronization</a>)</td>\n</tr>\n<tr>\n<td>shared managed <code>T</code></td>\n<td><code>&amp;exclusive T</code></td>\n<td>never: a shared managed handle cannot prove uniqueness</td>\n</tr>\n</tbody></table></div><p>Borrows can weaken freely, but cannot be upgraded (obviously):</p>\n<div class=\"markdown-table\" tabindex=\"0\"><table><thead><tr>\n<th>From</th>\n<th>To</th>\n<th>Notes</th>\n</tr>\n</thead><tbody><tr>\n<td><code>&amp;exclusive T</code></td>\n<td><code>&amp;T</code> / <code>&amp;readonly T</code></td>\n<td>temporary reborrow that suspends the exclusive loan</td>\n</tr>\n<tr>\n<td><code>&amp;T</code></td>\n<td><code>&amp;readonly T</code></td>\n<td>readonly reborrow</td>\n</tr>\n<tr>\n<td>managed reference <code>T</code></td>\n<td><code>^T</code></td>\n<td>never: managed ownership cannot become unique ownership</td>\n</tr>\n<tr>\n<td><code>&amp;T</code></td>\n<td><code>T</code> / <code>^T</code></td>\n<td>never: borrowed access does not own the value</td>\n</tr>\n</tbody></table></div><p>Raw pointers convert freely in, and only unsafely out:</p>\n<figure class=\"markdown-code\"><figcaption><span class=\"markdown-code__title\">Conversions</span><span class=\"markdown-code__format\">.ds</span></figcaption><pre tabindex=\"0\"><code class=\"markdown-code-lines\"><span class=\"markdown-code-line\"><span class=\"markdown-code-gutter\">1</span><span class=\"markdown-code-text\"><span data-k=\"keyword\">let</span> <span data-k=\"name\">user</span> <span data-k=\"punct\">=</span> <span data-k=\"keyword\">new</span> <span data-k=\"type\">User</span><span data-k=\"punct\">(</span><span data-k=\"punct\">)</span><span data-k=\"punct\">;</span></span></span><span class=\"markdown-code-line\"><span class=\"markdown-code-gutter\">2</span><span class=\"markdown-code-text\"> </span></span><span class=\"markdown-code-line\"><span class=\"markdown-code-gutter\">3</span><span class=\"markdown-code-text\"><span data-k=\"keyword\">let</span> <span data-k=\"name\">borrow</span><span data-k=\"punct\">:</span> <span data-k=\"punct\">&amp;</span><span data-k=\"type\">User</span> <span data-k=\"punct\">=</span> <span data-k=\"punct\">&amp;</span><span data-k=\"name\">user</span><span data-k=\"punct\">;</span>   <span data-k=\"comment\">// default: a checked borrow</span></span></span><span class=\"markdown-code-line\"><span class=\"markdown-code-gutter\">4</span><span class=\"markdown-code-text\"><span data-k=\"keyword\">let</span> <span data-k=\"name\">pointer</span><span data-k=\"punct\">:</span> <span data-k=\"punct\">*</span><span data-k=\"type\">User</span> <span data-k=\"punct\">=</span> <span data-k=\"punct\">&amp;</span><span data-k=\"name\">user</span><span data-k=\"punct\">;</span>  <span data-k=\"comment\">// typed as raw: an inert, unchecked pointer value</span></span></span><span class=\"markdown-code-line\"><span class=\"markdown-code-gutter\">5</span><span class=\"markdown-code-text\"><span data-k=\"keyword\">let</span> <span data-k=\"name\">again</span><span data-k=\"punct\">:</span> <span data-k=\"punct\">&amp;</span><span data-k=\"type\">User</span> <span data-k=\"punct\">=</span> <span data-k=\"name\">pointer</span><span data-k=\"punct\">;</span>  <span data-k=\"comment\">// ERROR: pointers only reborrow inside @unsafe</span></span></span></code></pre></figure><h2 id=\"unsafe\">Unsafe</h2><p>Safe Destack code can create and carry raw pointers, because there is nothing directly unsafe about just looking at pointers.\nRaw pointers are inert: they do not keep storage alive, do not participate in borrow checking, and do not prove exclusivity.</p>\n<p>Converting a borrow to a raw pointer is still safe because it does not touch the pointed-to memory:</p>\n<figure class=\"markdown-code\"><figcaption><span class=\"markdown-code__title\">Unsafe</span><span class=\"markdown-code__format\">.ds</span></figcaption><pre tabindex=\"0\"><code class=\"markdown-code-lines\"><span class=\"markdown-code-line\"><span class=\"markdown-code-gutter\">1</span><span class=\"markdown-code-text\"><span data-k=\"keyword\">let</span> <span data-k=\"name\">user</span> <span data-k=\"punct\">=</span> <span data-k=\"keyword\">new</span> <span data-k=\"type\">User</span><span data-k=\"punct\">(</span><span data-k=\"punct\">)</span><span data-k=\"punct\">;</span></span></span><span class=\"markdown-code-line\"><span class=\"markdown-code-gutter\">2</span><span class=\"markdown-code-text\"> </span></span><span class=\"markdown-code-line\"><span class=\"markdown-code-gutter\">3</span><span class=\"markdown-code-text\"><span data-k=\"keyword\">let</span> <span data-k=\"name\">borrow</span><span data-k=\"punct\">:</span> <span data-k=\"punct\">&amp;</span><span data-k=\"type\">User</span> <span data-k=\"punct\">=</span> <span data-k=\"punct\">&amp;</span><span data-k=\"name\">user</span><span data-k=\"punct\">;</span></span></span><span class=\"markdown-code-line\"><span class=\"markdown-code-gutter\">4</span><span class=\"markdown-code-text\"><span data-k=\"keyword\">let</span> <span data-k=\"name\">pointer</span><span data-k=\"punct\">:</span> <span data-k=\"punct\">*</span><span data-k=\"type\">User</span> <span data-k=\"punct\">=</span> <span data-k=\"name\">borrow</span><span data-k=\"punct\">;</span> <span data-k=\"comment\">// OK: this only creates a raw pointer value</span></span></span></code></pre></figure><p>Unsafe begins when code relies on a memory invariant the compiler cannot prove:</p>\n<div class=\"markdown-table\" tabindex=\"0\"><table><thead><tr>\n<th>Operation</th>\n<th>Example</th>\n<th>Safe?</th>\n<th>Why</th>\n</tr>\n</thead><tbody><tr>\n<td>create or carry raw pointer values</td>\n<td><code>let pointer: *User = &amp;user</code>, <code>pointer == other</code></td>\n<td>yes</td>\n<td>does not touch memory</td>\n</tr>\n<tr>\n<td>reinterpret raw pointer values</td>\n<td><code>pointer as *uint8</code>, <code>0x1000 as *uint8</code></td>\n<td>yes</td>\n<td>makes no validity claim</td>\n</tr>\n<tr>\n<td>wrapping address arithmetic</td>\n<td><code>wrappingOffset(pointer, 4)</code></td>\n<td>yes</td>\n<td>makes no allocation claim</td>\n</tr>\n<tr>\n<td>allocation-relative pointer math</td>\n<td><code>offset(pointer, 4)</code>, <code>offsetFrom(pointer, origin)</code></td>\n<td>no</td>\n<td>claims same live allocation</td>\n</tr>\n<tr>\n<td>access memory through a pointer</td>\n<td><code>asReference(pointer)</code>, <code>read(pointer)</code>, <code>write(pointer, value)</code></td>\n<td>no</td>\n<td>bypasses borrow checking</td>\n</tr>\n<tr>\n<td>build typed views from raw storage</td>\n<td><code>Slice.fromRaw(pointer, length)</code></td>\n<td>no</td>\n<td>claims a valid region of <code>T</code></td>\n</tr>\n<tr>\n<td>raw bytes and layout tricks</td>\n<td><code>copyBytes(dst, src, n)</code>, <code>readVolatile(pointer)</code>, <code>transmute&lt;T, U&gt;(value)</code></td>\n<td>no</td>\n<td>touches or reinterprets unchecked memory</td>\n</tr>\n</tbody></table></div><p>The compiler rejects unsafe operations, like raw pointer dereferencing, outside explicit <a href=\"/docs/language/expressions/#taint\"><code>@unsafe</code> / <code>@safe</code></a> contexts.</p>\n<h2 id=\"algebra\">Algebra</h2><p>Destack&#39;s &quot;memory algebra&quot; is a fancy way of saying that the axes of ownership, access, lifetime, and placement are just types that we can do TypeScript-style algebra and inference with.\nWe can inspect a type&#39;s memory form and build a derived form because all the qualified surface forms like <code>readonly T</code>, <code>^T</code>, <code>&amp;T</code>, <code>*T</code>, <code>local T</code>, and <code>shared T</code> correspond to builtin intrinsic types and rewrite helpers:</p>\n<figure class=\"markdown-code\"><figcaption><span class=\"markdown-code__title\">Algebra</span><span class=\"markdown-code__format\">.ds</span></figcaption><pre tabindex=\"0\"><code class=\"markdown-code-lines\"><span class=\"markdown-code-line\"><span class=\"markdown-code-gutter\">1</span><span class=\"markdown-code-text\"><span data-k=\"comment\">/// Automatically managed T, owned by the runtime.</span></span></span><span class=\"markdown-code-line\"><span class=\"markdown-code-gutter\">2</span><span class=\"markdown-code-text\"><span data-k=\"keyword\">newtype</span> <span data-k=\"type\">Managed</span><span data-k=\"punct\">&lt;</span><span data-k=\"type\">T</span><span data-k=\"punct\">&gt;</span> <span data-k=\"punct\">=</span> <span data-k=\"type\">intrinsic</span><span data-k=\"punct\">;</span></span></span><span class=\"markdown-code-line\"><span class=\"markdown-code-gutter\">3</span><span class=\"markdown-code-text\"><span data-k=\"comment\">/// Owned T (`^T`).</span></span></span><span class=\"markdown-code-line\"><span class=\"markdown-code-gutter\">4</span><span class=\"markdown-code-text\"><span data-k=\"keyword\">newtype</span> <span data-k=\"type\">Owned</span><span data-k=\"punct\">&lt;</span><span data-k=\"type\">T</span><span data-k=\"punct\">&gt;</span> <span data-k=\"punct\">=</span> <span data-k=\"type\">intrinsic</span><span data-k=\"punct\">;</span></span></span><span class=\"markdown-code-line\"><span class=\"markdown-code-gutter\">5</span><span class=\"markdown-code-text\"><span data-k=\"comment\">/// Borrowed T (`&amp;T`).</span></span></span><span class=\"markdown-code-line\"><span class=\"markdown-code-gutter\">6</span><span class=\"markdown-code-text\"><span data-k=\"keyword\">newtype</span> <span data-k=\"type\">Borrowed</span><span data-k=\"punct\">&lt;</span><span data-k=\"type\">T</span><span data-k=\"punct\">,</span> <span data-k=\"keyword\">comptime</span> <span data-k=\"type\">L</span><span data-k=\"punct\">:</span> <span data-k=\"type\">Lifetime</span><span data-k=\"punct\">,</span> <span data-k=\"keyword\">comptime</span> <span data-k=\"type\">A</span><span data-k=\"punct\">:</span> <span data-k=\"type\">Access</span> <span data-k=\"punct\">=</span> <span data-k=\"string\">&quot;mutable&quot;</span><span data-k=\"punct\">&gt;</span> <span data-k=\"punct\">=</span> <span data-k=\"type\">intrinsic</span><span data-k=\"punct\">;</span></span></span><span class=\"markdown-code-line\"><span class=\"markdown-code-gutter\">7</span><span class=\"markdown-code-text\"><span data-k=\"comment\">/// Raw T (`*T`).</span></span></span><span class=\"markdown-code-line\"><span class=\"markdown-code-gutter\">8</span><span class=\"markdown-code-text\"><span data-k=\"keyword\">newtype</span> <span data-k=\"type\">Raw</span><span data-k=\"punct\">&lt;</span><span data-k=\"type\">T</span><span data-k=\"punct\">&gt;</span> <span data-k=\"punct\">=</span> <span data-k=\"type\">intrinsic</span><span data-k=\"punct\">;</span></span></span><span class=\"markdown-code-line\"><span class=\"markdown-code-gutter\">9</span><span class=\"markdown-code-text\"><span data-k=\"comment\">/// Placed T (`local T` or `shared T`).</span></span></span><span class=\"markdown-code-line\"><span class=\"markdown-code-gutter\">10</span><span class=\"markdown-code-text\"><span data-k=\"keyword\">newtype</span> <span data-k=\"type\">Placed</span><span data-k=\"punct\">&lt;</span><span data-k=\"type\">T</span><span data-k=\"punct\">,</span> <span data-k=\"type\">P</span><span data-k=\"punct\">:</span> <span data-k=\"type\">Place</span><span data-k=\"punct\">&gt;</span> <span data-k=\"punct\">=</span> <span data-k=\"type\">intrinsic</span><span data-k=\"punct\">;</span></span></span></code></pre></figure><p>Specifically, all surface sigils and keywords are just compact syntax for those intrinsic forms that commute the way they read:</p>\n<figure class=\"markdown-code\"><figcaption><span class=\"markdown-code__title\">Algebra</span><span class=\"markdown-code__format\">.ds</span></figcaption><pre tabindex=\"0\"><code class=\"markdown-code-lines\"><span class=\"markdown-code-line\"><span class=\"markdown-code-gutter\">1</span><span class=\"markdown-code-text\"><span data-k=\"keyword\">declare</span> <span data-k=\"keyword\">class</span> <span data-k=\"type\">User</span> <span data-k=\"punct\">{</span> <span data-k=\"comment\">/* ... */</span> <span data-k=\"punct\">}</span><span data-k=\"punct\">;</span></span></span><span class=\"markdown-code-line\"><span class=\"markdown-code-gutter\">2</span><span class=\"markdown-code-text\"><span data-k=\"keyword\">declare</span> <span data-k=\"keyword\">struct</span> <span data-k=\"type\">Point</span> <span data-k=\"punct\">{</span> <span data-k=\"comment\">/* ... */</span> <span data-k=\"punct\">}</span><span data-k=\"punct\">;</span></span></span><span class=\"markdown-code-line\"><span class=\"markdown-code-gutter\">3</span><span class=\"markdown-code-text\"> </span></span><span class=\"markdown-code-line\"><span class=\"markdown-code-gutter\">4</span><span class=\"markdown-code-text\"><span data-k=\"keyword\">type</span> <span data-k=\"type\">NormalUser</span> <span data-k=\"punct\">=</span> <span data-k=\"type\">User</span><span data-k=\"punct\">;</span>                        <span data-k=\"comment\">// unqualified, normal default representation</span></span></span><span class=\"markdown-code-line\"><span class=\"markdown-code-gutter\">5</span><span class=\"markdown-code-text\"><span data-k=\"keyword\">type</span> <span data-k=\"type\">NormalPoint</span> <span data-k=\"punct\">=</span> <span data-k=\"type\">Point</span><span data-k=\"punct\">;</span>                      <span data-k=\"comment\">// unqualified value type, default-owned/direct</span></span></span><span class=\"markdown-code-line\"><span class=\"markdown-code-gutter\">6</span><span class=\"markdown-code-text\"><span data-k=\"keyword\">type</span> <span data-k=\"type\">ReadonlyUser</span> <span data-k=\"punct\">=</span> <span data-k=\"keyword\">readonly</span> <span data-k=\"type\">User</span><span data-k=\"punct\">;</span>             <span data-k=\"comment\">// WithAccess&lt;User, &quot;readonly&quot;&gt;</span></span></span><span class=\"markdown-code-line\"><span class=\"markdown-code-gutter\">7</span><span class=\"markdown-code-text\"><span data-k=\"keyword\">type</span> <span data-k=\"type\">OwnedUser</span> <span data-k=\"punct\">=</span> <span data-k=\"punct\">^</span><span data-k=\"type\">User</span><span data-k=\"punct\">;</span>                        <span data-k=\"comment\">// Owned&lt;User&gt;</span></span></span><span class=\"markdown-code-line\"><span class=\"markdown-code-gutter\">8</span><span class=\"markdown-code-text\"><span data-k=\"keyword\">type</span> <span data-k=\"type\">OwnedPoint</span> <span data-k=\"punct\">=</span> <span data-k=\"punct\">^</span><span data-k=\"type\">Point</span><span data-k=\"punct\">;</span>                      <span data-k=\"comment\">// Owned&lt;Point&gt;, reduced to Point</span></span></span><span class=\"markdown-code-line\"><span class=\"markdown-code-gutter\">9</span><span class=\"markdown-code-text\"><span data-k=\"keyword\">type</span> <span data-k=\"type\">ReadonlyBorrowedUser</span> <span data-k=\"punct\">=</span> <span data-k=\"punct\">&amp;</span><span data-k=\"keyword\">readonly</span> <span data-k=\"type\">User</span><span data-k=\"punct\">;</span>    <span data-k=\"comment\">// Borrowed&lt;User, L, &quot;readonly&quot;&gt;</span></span></span><span class=\"markdown-code-line\"><span class=\"markdown-code-gutter\">10</span><span class=\"markdown-code-text\"><span data-k=\"keyword\">type</span> <span data-k=\"type\">BorrowedUser</span> <span data-k=\"punct\">=</span> <span data-k=\"punct\">&amp;</span><span data-k=\"type\">User</span><span data-k=\"punct\">;</span>                     <span data-k=\"comment\">// Borrowed&lt;User, L, &quot;mutable&quot;&gt;</span></span></span><span class=\"markdown-code-line\"><span class=\"markdown-code-gutter\">11</span><span class=\"markdown-code-text\"><span data-k=\"keyword\">type</span> <span data-k=\"type\">ExclusiveBorrowedUser</span> <span data-k=\"punct\">=</span> <span data-k=\"punct\">&amp;</span>exclusive <span data-k=\"type\">User</span><span data-k=\"punct\">;</span>  <span data-k=\"comment\">// Borrowed&lt;User, L, &quot;exclusive&quot;&gt;</span></span></span><span class=\"markdown-code-line\"><span class=\"markdown-code-gutter\">12</span><span class=\"markdown-code-text\"><span data-k=\"keyword\">type</span> <span data-k=\"type\">RawUser</span> <span data-k=\"punct\">=</span> <span data-k=\"punct\">*</span><span data-k=\"type\">User</span><span data-k=\"punct\">;</span>                          <span data-k=\"comment\">// Raw&lt;User&gt;</span></span></span><span class=\"markdown-code-line\"><span class=\"markdown-code-gutter\">13</span><span class=\"markdown-code-text\"><span data-k=\"keyword\">type</span> <span data-k=\"type\">LocalUser</span> <span data-k=\"punct\">=</span> local <span data-k=\"type\">User</span><span data-k=\"punct\">;</span>                   <span data-k=\"comment\">// Placed&lt;User, &quot;local&quot;&gt;</span></span></span><span class=\"markdown-code-line\"><span class=\"markdown-code-gutter\">14</span><span class=\"markdown-code-text\"><span data-k=\"keyword\">type</span> <span data-k=\"type\">SharedUser</span> <span data-k=\"punct\">=</span> shared <span data-k=\"type\">User</span><span data-k=\"punct\">;</span>                 <span data-k=\"comment\">// Placed&lt;User, &quot;shared&quot;&gt;</span></span></span><span class=\"markdown-code-line\"><span class=\"markdown-code-gutter\">15</span><span class=\"markdown-code-text\"><span data-k=\"keyword\">type</span> <span data-k=\"type\">LocalOwnedUser</span> <span data-k=\"punct\">=</span> local <span data-k=\"punct\">^</span><span data-k=\"type\">User</span><span data-k=\"punct\">;</span>             <span data-k=\"comment\">// Placed&lt;Owned&lt;User&gt;, &quot;local&quot;&gt;</span></span></span><span class=\"markdown-code-line\"><span class=\"markdown-code-gutter\">16</span><span class=\"markdown-code-text\"><span data-k=\"keyword\">type</span> <span data-k=\"type\">SharedOwnedUser</span> <span data-k=\"punct\">=</span> shared <span data-k=\"punct\">^</span><span data-k=\"type\">User</span><span data-k=\"punct\">;</span>           <span data-k=\"comment\">// Placed&lt;Owned&lt;User&gt;, &quot;shared&quot;&gt;</span></span></span><span class=\"markdown-code-line\"><span class=\"markdown-code-gutter\">17</span><span class=\"markdown-code-text\"><span data-k=\"keyword\">type</span> <span data-k=\"type\">OwnedSharedUser</span> <span data-k=\"punct\">=</span> <span data-k=\"punct\">^</span>shared <span data-k=\"type\">User</span><span data-k=\"punct\">;</span>           <span data-k=\"comment\">// Owned&lt;Placed&lt;User, &quot;shared&quot;&gt;&gt;</span></span></span></code></pre></figure><p>It follows that because forms compose, owning a borrow is different from borrowing an owner:</p>\n<figure class=\"markdown-code\"><figcaption><span class=\"markdown-code__title\">Algebra</span><span class=\"markdown-code__format\">.ds</span></figcaption><pre tabindex=\"0\"><code class=\"markdown-code-lines\"><span class=\"markdown-code-line\"><span class=\"markdown-code-gutter\">1</span><span class=\"markdown-code-text\"><span data-k=\"type\">Owned</span><span data-k=\"punct\">&lt;</span><span data-k=\"type\">Borrowed</span><span data-k=\"punct\">&lt;</span><span data-k=\"type\">User</span><span data-k=\"punct\">,</span> <span data-k=\"type\">L</span><span data-k=\"punct\">&gt;</span><span data-k=\"punct\">&gt;</span> <span data-k=\"comment\">// owns a borrow value</span></span></span><span class=\"markdown-code-line\"><span class=\"markdown-code-gutter\">2</span><span class=\"markdown-code-text\"><span data-k=\"type\">Borrowed</span><span data-k=\"punct\">&lt;</span><span data-k=\"type\">Owned</span><span data-k=\"punct\">&lt;</span><span data-k=\"type\">User</span><span data-k=\"punct\">&gt;</span><span data-k=\"punct\">,</span> <span data-k=\"type\">L</span><span data-k=\"punct\">&gt;</span> <span data-k=\"comment\">// borrows an owned value</span></span></span></code></pre></figure><p>Destack also provides builtin accessors to inspect composed forms, e.g., <code>PayloadOf&lt;T&gt;</code> removes one outer form, while <code>BaseOf&lt;T&gt;</code> removes all transparent memory forms:</p>\n<figure class=\"markdown-code\"><figcaption><span class=\"markdown-code__title\">Algebra</span><span class=\"markdown-code__format\">.ds</span></figcaption><pre tabindex=\"0\"><code class=\"markdown-code-lines\"><span class=\"markdown-code-line\"><span class=\"markdown-code-gutter\">1</span><span class=\"markdown-code-text\"><span data-k=\"type\">BaseOf</span><span data-k=\"punct\">&lt;</span>shared <span data-k=\"punct\">^</span><span data-k=\"type\">User</span><span data-k=\"punct\">&gt;</span> <span data-k=\"keyword\">satisfies</span> <span data-k=\"type\">User</span><span data-k=\"punct\">;</span></span></span><span class=\"markdown-code-line\"><span class=\"markdown-code-gutter\">2</span><span class=\"markdown-code-text\"><span data-k=\"type\">PayloadOf</span><span data-k=\"punct\">&lt;</span><span data-k=\"type\">Owned</span><span data-k=\"punct\">&lt;</span><span data-k=\"type\">Borrowed</span><span data-k=\"punct\">&lt;</span><span data-k=\"type\">User</span><span data-k=\"punct\">,</span> <span data-k=\"type\">L</span><span data-k=\"punct\">&gt;</span><span data-k=\"punct\">&gt;</span><span data-k=\"punct\">&gt;</span> <span data-k=\"keyword\">satisfies</span> <span data-k=\"type\">Borrowed</span><span data-k=\"punct\">&lt;</span><span data-k=\"type\">User</span><span data-k=\"punct\">,</span> <span data-k=\"type\">L</span><span data-k=\"punct\">&gt;</span><span data-k=\"punct\">;</span></span></span><span class=\"markdown-code-line\"><span class=\"markdown-code-gutter\">3</span><span class=\"markdown-code-text\"><span data-k=\"type\">OwnershipOf</span><span data-k=\"punct\">&lt;</span><span data-k=\"punct\">^</span><span data-k=\"type\">User</span><span data-k=\"punct\">&gt;</span> <span data-k=\"keyword\">satisfies</span> <span data-k=\"string\">&quot;owned&quot;</span><span data-k=\"punct\">;</span></span></span><span class=\"markdown-code-line\"><span class=\"markdown-code-gutter\">4</span><span class=\"markdown-code-text\"><span data-k=\"type\">OwnershipOf</span><span data-k=\"punct\">&lt;</span><span data-k=\"type\">Point</span><span data-k=\"punct\">&gt;</span> <span data-k=\"keyword\">satisfies</span> <span data-k=\"string\">&quot;owned&quot;</span><span data-k=\"punct\">;</span></span></span><span class=\"markdown-code-line\"><span class=\"markdown-code-gutter\">5</span><span class=\"markdown-code-text\"><span data-k=\"type\">OwnershipOf</span><span data-k=\"punct\">&lt;</span><span data-k=\"type\">User</span><span data-k=\"punct\">&gt;</span> <span data-k=\"keyword\">satisfies</span> <span data-k=\"string\">&quot;managed&quot;</span><span data-k=\"punct\">;</span></span></span><span class=\"markdown-code-line\"><span class=\"markdown-code-gutter\">6</span><span class=\"markdown-code-text\"><span data-k=\"type\">OwnershipOf</span><span data-k=\"punct\">&lt;</span><span data-k=\"type\">Owned</span><span data-k=\"punct\">&lt;</span><span data-k=\"type\">Borrowed</span><span data-k=\"punct\">&lt;</span><span data-k=\"type\">User</span><span data-k=\"punct\">,</span> <span data-k=\"type\">L</span><span data-k=\"punct\">&gt;</span><span data-k=\"punct\">&gt;</span><span data-k=\"punct\">&gt;</span> <span data-k=\"keyword\">satisfies</span> <span data-k=\"string\">&quot;owned&quot;</span><span data-k=\"punct\">;</span></span></span><span class=\"markdown-code-line\"><span class=\"markdown-code-gutter\">7</span><span class=\"markdown-code-text\"><span data-k=\"type\">OwnershipOf</span><span data-k=\"punct\">&lt;</span><span data-k=\"type\">Borrowed</span><span data-k=\"punct\">&lt;</span><span data-k=\"type\">Owned</span><span data-k=\"punct\">&lt;</span><span data-k=\"type\">User</span><span data-k=\"punct\">&gt;</span><span data-k=\"punct\">,</span> <span data-k=\"type\">L</span><span data-k=\"punct\">&gt;</span><span data-k=\"punct\">&gt;</span> <span data-k=\"keyword\">satisfies</span> <span data-k=\"string\">&quot;borrowed&quot;</span><span data-k=\"punct\">;</span></span></span><span class=\"markdown-code-line\"><span class=\"markdown-code-gutter\">8</span><span class=\"markdown-code-text\"><span data-k=\"type\">OwnershipOr</span><span data-k=\"punct\">&lt;</span><span data-k=\"type\">User</span><span data-k=\"punct\">,</span> <span data-k=\"string\">&quot;managed&quot;</span><span data-k=\"punct\">&gt;</span> <span data-k=\"keyword\">satisfies</span> <span data-k=\"string\">&quot;managed&quot;</span><span data-k=\"punct\">;</span></span></span><span class=\"markdown-code-line\"><span class=\"markdown-code-gutter\">9</span><span class=\"markdown-code-text\"><span data-k=\"type\">AccessOf</span><span data-k=\"punct\">&lt;</span><span data-k=\"type\">User</span><span data-k=\"punct\">&gt;</span> <span data-k=\"keyword\">satisfies</span> <span data-k=\"string\">&quot;mutable&quot;</span><span data-k=\"punct\">;</span></span></span><span class=\"markdown-code-line\"><span class=\"markdown-code-gutter\">10</span><span class=\"markdown-code-text\"><span data-k=\"type\">AccessOf</span><span data-k=\"punct\">&lt;</span><span data-k=\"keyword\">readonly</span> <span data-k=\"type\">User</span><span data-k=\"punct\">&gt;</span> <span data-k=\"keyword\">satisfies</span> <span data-k=\"string\">&quot;readonly&quot;</span><span data-k=\"punct\">;</span></span></span><span class=\"markdown-code-line\"><span class=\"markdown-code-gutter\">11</span><span class=\"markdown-code-text\"><span data-k=\"type\">AccessOf</span><span data-k=\"punct\">&lt;</span><span data-k=\"punct\">^</span><span data-k=\"keyword\">readonly</span> <span data-k=\"type\">User</span><span data-k=\"punct\">&gt;</span> <span data-k=\"keyword\">satisfies</span> <span data-k=\"string\">&quot;readonly&quot;</span><span data-k=\"punct\">;</span></span></span><span class=\"markdown-code-line\"><span class=\"markdown-code-gutter\">12</span><span class=\"markdown-code-text\"><span data-k=\"type\">AccessOf</span><span data-k=\"punct\">&lt;</span><span data-k=\"punct\">&amp;</span>exclusive <span data-k=\"type\">User</span><span data-k=\"punct\">&gt;</span> <span data-k=\"keyword\">satisfies</span> <span data-k=\"string\">&quot;exclusive&quot;</span><span data-k=\"punct\">;</span></span></span></code></pre></figure><p><code>Space</code> represents one builtin concrete space while <code>Place</code> means either a concrete <code>Space</code> or <code>&quot;ambient&quot;</code>, and ambient placement follows the containing context until a final layout is required:</p>\n<figure class=\"markdown-code\"><figcaption><span class=\"markdown-code__title\">Algebra</span><span class=\"markdown-code__format\">.ds</span></figcaption><pre tabindex=\"0\"><code class=\"markdown-code-lines\"><span class=\"markdown-code-line\"><span class=\"markdown-code-gutter\">1</span><span class=\"markdown-code-text\"><span data-k=\"type\">PlaceOf</span><span data-k=\"punct\">&lt;</span><span data-k=\"type\">User</span><span data-k=\"punct\">&gt;</span> <span data-k=\"keyword\">satisfies</span> <span data-k=\"string\">&quot;ambient&quot;</span><span data-k=\"punct\">;</span></span></span><span class=\"markdown-code-line\"><span class=\"markdown-code-gutter\">2</span><span class=\"markdown-code-text\"><span data-k=\"type\">SpaceOf</span><span data-k=\"punct\">&lt;</span><span data-k=\"punct\">^</span><span data-k=\"type\">User</span><span data-k=\"punct\">&gt;</span> <span data-k=\"keyword\">satisfies</span> <span data-k=\"type\">never</span><span data-k=\"punct\">;</span></span></span><span class=\"markdown-code-line\"><span class=\"markdown-code-gutter\">3</span><span class=\"markdown-code-text\"><span data-k=\"type\">PlaceIn</span><span data-k=\"punct\">&lt;</span><span data-k=\"punct\">^</span><span data-k=\"type\">User</span><span data-k=\"punct\">,</span> <span data-k=\"string\">&quot;shared&quot;</span><span data-k=\"punct\">&gt;</span> <span data-k=\"keyword\">satisfies</span> <span data-k=\"string\">&quot;shared&quot;</span><span data-k=\"punct\">;</span></span></span><span class=\"markdown-code-line\"><span class=\"markdown-code-gutter\">4</span><span class=\"markdown-code-text\"> </span></span><span class=\"markdown-code-line\"><span class=\"markdown-code-gutter\">5</span><span class=\"markdown-code-text\"><span data-k=\"type\">PlaceOf</span><span data-k=\"punct\">&lt;</span>local <span data-k=\"type\">User</span><span data-k=\"punct\">&gt;</span> <span data-k=\"keyword\">satisfies</span> <span data-k=\"string\">&quot;local&quot;</span><span data-k=\"punct\">;</span></span></span><span class=\"markdown-code-line\"><span class=\"markdown-code-gutter\">6</span><span class=\"markdown-code-text\"><span data-k=\"type\">SpaceOf</span><span data-k=\"punct\">&lt;</span>local <span data-k=\"type\">User</span><span data-k=\"punct\">&gt;</span> <span data-k=\"keyword\">satisfies</span> <span data-k=\"string\">&quot;local&quot;</span><span data-k=\"punct\">;</span></span></span><span class=\"markdown-code-line\"><span class=\"markdown-code-gutter\">7</span><span class=\"markdown-code-text\"><span data-k=\"type\">PlaceIn</span><span data-k=\"punct\">&lt;</span>local <span data-k=\"type\">User</span><span data-k=\"punct\">,</span> <span data-k=\"string\">&quot;shared&quot;</span><span data-k=\"punct\">&gt;</span> <span data-k=\"keyword\">satisfies</span> <span data-k=\"string\">&quot;local&quot;</span><span data-k=\"punct\">;</span></span></span><span class=\"markdown-code-line\"><span class=\"markdown-code-gutter\">8</span><span class=\"markdown-code-text\"> </span></span><span class=\"markdown-code-line\"><span class=\"markdown-code-gutter\">9</span><span class=\"markdown-code-text\"><span data-k=\"type\">PlaceOf</span><span data-k=\"punct\">&lt;</span>shared <span data-k=\"type\">User</span><span data-k=\"punct\">&gt;</span> <span data-k=\"keyword\">satisfies</span> <span data-k=\"string\">&quot;shared&quot;</span><span data-k=\"punct\">;</span></span></span><span class=\"markdown-code-line\"><span class=\"markdown-code-gutter\">10</span><span class=\"markdown-code-text\"><span data-k=\"type\">SpaceOf</span><span data-k=\"punct\">&lt;</span>shared <span data-k=\"type\">User</span><span data-k=\"punct\">&gt;</span> <span data-k=\"keyword\">satisfies</span> <span data-k=\"string\">&quot;shared&quot;</span><span data-k=\"punct\">;</span></span></span><span class=\"markdown-code-line\"><span class=\"markdown-code-gutter\">11</span><span class=\"markdown-code-text\"><span data-k=\"type\">PlaceIn</span><span data-k=\"punct\">&lt;</span>shared <span data-k=\"type\">User</span><span data-k=\"punct\">,</span> <span data-k=\"string\">&quot;local&quot;</span><span data-k=\"punct\">&gt;</span> <span data-k=\"keyword\">satisfies</span> <span data-k=\"string\">&quot;shared&quot;</span><span data-k=\"punct\">;</span></span></span><span class=\"markdown-code-line\"><span class=\"markdown-code-gutter\">12</span><span class=\"markdown-code-text\"> </span></span><span class=\"markdown-code-line\"><span class=\"markdown-code-gutter\">13</span><span class=\"markdown-code-text\"><span data-k=\"type\">PlaceOf</span><span data-k=\"punct\">&lt;</span><span data-k=\"type\">User</span> <span data-k=\"punct\">|</span> local <span data-k=\"type\">User</span> <span data-k=\"punct\">|</span> shared <span data-k=\"type\">User</span><span data-k=\"punct\">&gt;</span> <span data-k=\"keyword\">satisfies</span> <span data-k=\"string\">&quot;ambient&quot;</span> <span data-k=\"punct\">|</span> <span data-k=\"string\">&quot;local&quot;</span> <span data-k=\"punct\">|</span> <span data-k=\"string\">&quot;shared&quot;</span><span data-k=\"punct\">;</span></span></span><span class=\"markdown-code-line\"><span class=\"markdown-code-gutter\">14</span><span class=\"markdown-code-text\"><span data-k=\"type\">SpaceOf</span><span data-k=\"punct\">&lt;</span><span data-k=\"type\">User</span> <span data-k=\"punct\">|</span> local <span data-k=\"type\">User</span> <span data-k=\"punct\">|</span> shared <span data-k=\"type\">User</span><span data-k=\"punct\">&gt;</span> <span data-k=\"keyword\">satisfies</span> <span data-k=\"string\">&quot;local&quot;</span> <span data-k=\"punct\">|</span> <span data-k=\"string\">&quot;shared&quot;</span><span data-k=\"punct\">;</span></span></span><span class=\"markdown-code-line\"><span class=\"markdown-code-gutter\">15</span><span class=\"markdown-code-text\"><span data-k=\"type\">PlaceIn</span><span data-k=\"punct\">&lt;</span><span data-k=\"type\">User</span> <span data-k=\"punct\">|</span> local <span data-k=\"type\">User</span> <span data-k=\"punct\">|</span> shared <span data-k=\"type\">User</span><span data-k=\"punct\">,</span> <span data-k=\"string\">&quot;local&quot;</span><span data-k=\"punct\">&gt;</span> <span data-k=\"keyword\">satisfies</span> <span data-k=\"string\">&quot;local&quot;</span> <span data-k=\"punct\">|</span> <span data-k=\"string\">&quot;shared&quot;</span><span data-k=\"punct\">;</span></span></span><span class=\"markdown-code-line\"><span class=\"markdown-code-gutter\">16</span><span class=\"markdown-code-text\"><span data-k=\"type\">PlaceIn</span><span data-k=\"punct\">&lt;</span><span data-k=\"type\">User</span> <span data-k=\"punct\">|</span> local <span data-k=\"type\">User</span> <span data-k=\"punct\">|</span> shared <span data-k=\"type\">User</span><span data-k=\"punct\">,</span> <span data-k=\"string\">&quot;shared&quot;</span><span data-k=\"punct\">&gt;</span> <span data-k=\"keyword\">satisfies</span> <span data-k=\"string\">&quot;local&quot;</span> <span data-k=\"punct\">|</span> <span data-k=\"string\">&quot;shared&quot;</span><span data-k=\"punct\">;</span></span></span></code></pre></figure><p>Predicates with <code>Is*</code> are convenience wrappers around those same accessors:</p>\n<figure class=\"markdown-code\"><figcaption><span class=\"markdown-code__title\">Algebra</span><span class=\"markdown-code__format\">.ds</span></figcaption><pre tabindex=\"0\"><code class=\"markdown-code-lines\"><span class=\"markdown-code-line\"><span class=\"markdown-code-gutter\">1</span><span class=\"markdown-code-text\"><span data-k=\"type\">IsOwned</span><span data-k=\"punct\">&lt;</span><span data-k=\"punct\">^</span><span data-k=\"type\">User</span><span data-k=\"punct\">&gt;</span> <span data-k=\"keyword\">satisfies</span> <span data-k=\"literal\">true</span><span data-k=\"punct\">;</span></span></span><span class=\"markdown-code-line\"><span class=\"markdown-code-gutter\">2</span><span class=\"markdown-code-text\"><span data-k=\"type\">IsBorrowed</span><span data-k=\"punct\">&lt;</span><span data-k=\"punct\">&amp;</span><span data-k=\"type\">User</span><span data-k=\"punct\">&gt;</span> <span data-k=\"keyword\">satisfies</span> <span data-k=\"literal\">true</span><span data-k=\"punct\">;</span></span></span><span class=\"markdown-code-line\"><span class=\"markdown-code-gutter\">3</span><span class=\"markdown-code-text\"><span data-k=\"type\">IsShared</span><span data-k=\"punct\">&lt;</span>shared <span data-k=\"type\">User</span><span data-k=\"punct\">&gt;</span> <span data-k=\"keyword\">satisfies</span> <span data-k=\"literal\">true</span><span data-k=\"punct\">;</span></span></span><span class=\"markdown-code-line\"><span class=\"markdown-code-gutter\">4</span><span class=\"markdown-code-text\"><span data-k=\"type\">IsShared</span><span data-k=\"punct\">&lt;</span><span data-k=\"punct\">^</span><span data-k=\"type\">User</span><span data-k=\"punct\">&gt;</span> <span data-k=\"keyword\">satisfies</span> <span data-k=\"literal\">false</span><span data-k=\"punct\">;</span></span></span><span class=\"markdown-code-line\"><span class=\"markdown-code-gutter\">5</span><span class=\"markdown-code-text\"><span data-k=\"type\">IsSharedIn</span><span data-k=\"punct\">&lt;</span><span data-k=\"punct\">^</span><span data-k=\"type\">User</span><span data-k=\"punct\">,</span> <span data-k=\"string\">&quot;shared&quot;</span><span data-k=\"punct\">&gt;</span> <span data-k=\"keyword\">satisfies</span> <span data-k=\"literal\">true</span><span data-k=\"punct\">;</span></span></span></code></pre></figure><p>Rewriting helpers preserve the rest of the type instead of rebuilding from a stripped base type:</p>\n<figure class=\"markdown-code\"><figcaption><span class=\"markdown-code__title\">Algebra</span><span class=\"markdown-code__format\">.ds</span></figcaption><pre tabindex=\"0\"><code class=\"markdown-code-lines\"><span class=\"markdown-code-line\"><span class=\"markdown-code-gutter\">1</span><span class=\"markdown-code-text\"><span data-k=\"type\">WithSpace</span><span data-k=\"punct\">&lt;</span><span data-k=\"punct\">^</span><span data-k=\"type\">User</span><span data-k=\"punct\">,</span> <span data-k=\"string\">&quot;shared&quot;</span><span data-k=\"punct\">&gt;</span> <span data-k=\"keyword\">satisfies</span> <span data-k=\"type\">Placed</span><span data-k=\"punct\">&lt;</span><span data-k=\"punct\">^</span><span data-k=\"type\">User</span><span data-k=\"punct\">,</span> <span data-k=\"string\">&quot;shared&quot;</span><span data-k=\"punct\">&gt;</span><span data-k=\"punct\">;</span></span></span><span class=\"markdown-code-line\"><span class=\"markdown-code-gutter\">2</span><span class=\"markdown-code-text\"><span data-k=\"type\">WithOwnership</span><span data-k=\"punct\">&lt;</span>shared <span data-k=\"type\">User</span><span data-k=\"punct\">,</span> <span data-k=\"string\">&quot;owned&quot;</span><span data-k=\"punct\">&gt;</span> <span data-k=\"keyword\">satisfies</span> <span data-k=\"type\">Owned</span><span data-k=\"punct\">&lt;</span>shared <span data-k=\"type\">User</span><span data-k=\"punct\">&gt;</span><span data-k=\"punct\">;</span></span></span><span class=\"markdown-code-line\"><span class=\"markdown-code-gutter\">3</span><span class=\"markdown-code-text\"><span data-k=\"type\">WithPlace</span><span data-k=\"punct\">&lt;</span>shared <span data-k=\"type\">User</span><span data-k=\"punct\">,</span> <span data-k=\"string\">&quot;ambient&quot;</span><span data-k=\"punct\">&gt;</span> <span data-k=\"keyword\">satisfies</span> <span data-k=\"type\">Placed</span><span data-k=\"punct\">&lt;</span><span data-k=\"type\">User</span><span data-k=\"punct\">,</span> <span data-k=\"string\">&quot;ambient&quot;</span><span data-k=\"punct\">&gt;</span><span data-k=\"punct\">;</span></span></span><span class=\"markdown-code-line\"><span class=\"markdown-code-gutter\">4</span><span class=\"markdown-code-text\"><span data-k=\"type\">WithAccess</span><span data-k=\"punct\">&lt;</span><span data-k=\"type\">User</span><span data-k=\"punct\">,</span> <span data-k=\"string\">&quot;readonly&quot;</span><span data-k=\"punct\">&gt;</span> <span data-k=\"keyword\">satisfies</span> <span data-k=\"keyword\">readonly</span> <span data-k=\"type\">User</span><span data-k=\"punct\">;</span></span></span><span class=\"markdown-code-line\"><span class=\"markdown-code-gutter\">5</span><span class=\"markdown-code-text\"><span data-k=\"type\">WithAccess</span><span data-k=\"punct\">&lt;</span><span data-k=\"punct\">^</span><span data-k=\"type\">User</span><span data-k=\"punct\">,</span> <span data-k=\"string\">&quot;readonly&quot;</span><span data-k=\"punct\">&gt;</span> <span data-k=\"keyword\">satisfies</span> <span data-k=\"punct\">^</span><span data-k=\"keyword\">readonly</span> <span data-k=\"type\">User</span><span data-k=\"punct\">;</span></span></span><span class=\"markdown-code-line\"><span class=\"markdown-code-gutter\">6</span><span class=\"markdown-code-text\"><span data-k=\"type\">WithAccess</span><span data-k=\"punct\">&lt;</span><span data-k=\"punct\">&amp;</span><span data-k=\"type\">User</span><span data-k=\"punct\">,</span> <span data-k=\"string\">&quot;exclusive&quot;</span><span data-k=\"punct\">&gt;</span> <span data-k=\"keyword\">satisfies</span> <span data-k=\"punct\">&amp;</span>exclusive <span data-k=\"type\">User</span><span data-k=\"punct\">;</span></span></span></code></pre></figure><p>Because memory qualification is just ordinary type-level computation, userland code can introspect and rewrite ownership and placement using the same type system we already use for all other types.\nInside a type declaration, <code>this</code> in type or static position also carries the current instantiated form of that type to query against with the <code>*Of</code> and <code>Is*</code> family.</p>\n<figure class=\"markdown-code\"><figcaption><span class=\"markdown-code__title\">Algebra</span><span class=\"markdown-code__format\">.ds</span></figcaption><pre tabindex=\"0\"><code class=\"markdown-code-lines\"><span class=\"markdown-code-line\"><span class=\"markdown-code-gutter\">1</span><span class=\"markdown-code-text\"><span data-k=\"keyword\">struct</span> <span data-k=\"type\">Buffer</span><span data-k=\"punct\">&lt;</span><span data-k=\"type\">T</span><span data-k=\"punct\">&gt;</span> <span data-k=\"punct\">{</span></span></span><span class=\"markdown-code-line\"><span class=\"markdown-code-gutter\">2</span><span class=\"markdown-code-text\">    <span data-k=\"property\">lock</span><span data-k=\"punct\">:</span> <span data-k=\"type\">PlaceOf</span><span data-k=\"punct\">&lt;</span>this<span data-k=\"punct\">&gt;</span> <span data-k=\"punct\">==</span> <span data-k=\"string\">&quot;shared&quot;</span> <span data-k=\"punct\">?</span> <span data-k=\"type\">Mutex</span> <span data-k=\"punct\">:</span> <span data-k=\"punct\">(</span><span data-k=\"punct\">)</span><span data-k=\"punct\">;</span></span></span><span class=\"markdown-code-line\"><span class=\"markdown-code-gutter\">3</span><span class=\"markdown-code-text\">    <span data-k=\"property\">value</span><span data-k=\"punct\">:</span> <span data-k=\"type\">T</span><span data-k=\"punct\">;</span></span></span><span class=\"markdown-code-line\"><span class=\"markdown-code-gutter\">4</span><span class=\"markdown-code-text\"><span data-k=\"punct\">}</span></span></span><span class=\"markdown-code-line\"><span class=\"markdown-code-gutter\">5</span><span class=\"markdown-code-text\"> </span></span><span class=\"markdown-code-line\"><span class=\"markdown-code-gutter\">6</span><span class=\"markdown-code-text\"><span data-k=\"keyword\">declare</span> <span data-k=\"keyword\">const</span> <span data-k=\"name\">localBuffer</span><span data-k=\"punct\">:</span> <span data-k=\"type\">Buffer</span><span data-k=\"punct\">&lt;</span><span data-k=\"type\">string</span><span data-k=\"punct\">&gt;</span><span data-k=\"punct\">;</span></span></span><span class=\"markdown-code-line\"><span class=\"markdown-code-gutter\">7</span><span class=\"markdown-code-text\"><span data-k=\"keyword\">declare</span> <span data-k=\"keyword\">const</span> <span data-k=\"name\">sharedBuffer</span><span data-k=\"punct\">:</span> shared <span data-k=\"type\">Buffer</span><span data-k=\"punct\">&lt;</span><span data-k=\"type\">string</span><span data-k=\"punct\">&gt;</span><span data-k=\"punct\">;</span></span></span><span class=\"markdown-code-line\"><span class=\"markdown-code-gutter\">8</span><span class=\"markdown-code-text\"> </span></span><span class=\"markdown-code-line\"><span class=\"markdown-code-gutter\">9</span><span class=\"markdown-code-text\"><span data-k=\"name\">sharedBuffer</span><span data-k=\"punct\">.</span><span data-k=\"property\">lock</span> <span data-k=\"keyword\">satisfies</span> <span data-k=\"type\">Mutex</span><span data-k=\"punct\">;</span></span></span><span class=\"markdown-code-line\"><span class=\"markdown-code-gutter\">10</span><span class=\"markdown-code-text\"><span data-k=\"name\">localBuffer</span><span data-k=\"punct\">.</span><span data-k=\"property\">lock</span> <span data-k=\"keyword\">satisfies</span> <span data-k=\"punct\">(</span><span data-k=\"punct\">)</span><span data-k=\"punct\">;</span></span></span><span class=\"markdown-code-line\"><span class=\"markdown-code-gutter\">11</span><span class=\"markdown-code-text\"><span data-k=\"type\">PlaceOf</span><span data-k=\"punct\">&lt;</span><span data-k=\"keyword\">typeof</span> <span data-k=\"name\">localBuffer</span><span data-k=\"punct\">&gt;</span> <span data-k=\"keyword\">satisfies</span> <span data-k=\"string\">&quot;ambient&quot;</span><span data-k=\"punct\">;</span></span></span><span class=\"markdown-code-line\"><span class=\"markdown-code-gutter\">12</span><span class=\"markdown-code-text\"><span data-k=\"type\">PlaceOf</span><span data-k=\"punct\">&lt;</span><span data-k=\"keyword\">typeof</span> <span data-k=\"name\">sharedBuffer</span><span data-k=\"punct\">&gt;</span> <span data-k=\"keyword\">satisfies</span> <span data-k=\"string\">&quot;shared&quot;</span><span data-k=\"punct\">;</span></span></span></code></pre></figure><h2 id=\"polymorphism\">Polymorphism</h2><p>Since ownership, access, lifetime, and placement are all reified as memory form types, contracts and implementors get to be polymorphic and (somewhat) conditional over their ownership, space, and access, even on the receiver type.\nThat lets types expose one natural operation when only the projected form changes, and separate operations when the semantics actually differ.\nThe caller chooses the level of control by writing the expression / providing the type they mean:</p>\n<figure class=\"markdown-code\"><figcaption><span class=\"markdown-code__title\">Polymorphism</span><span class=\"markdown-code__format\">.ds</span></figcaption><pre tabindex=\"0\"><code class=\"markdown-code-lines\"><span class=\"markdown-code-line\"><span class=\"markdown-code-gutter\">1</span><span class=\"markdown-code-text\"><span data-k=\"function\">process</span><span data-k=\"punct\">(</span><span data-k=\"name\">user</span><span data-k=\"punct\">)</span><span data-k=\"punct\">;</span>            <span data-k=\"comment\">// managed/default value</span></span></span><span class=\"markdown-code-line\"><span class=\"markdown-code-gutter\">2</span><span class=\"markdown-code-text\"><span data-k=\"function\">process</span><span data-k=\"punct\">(</span><span data-k=\"punct\">&amp;</span><span data-k=\"keyword\">readonly</span> <span data-k=\"name\">user</span><span data-k=\"punct\">)</span><span data-k=\"punct\">;</span>  <span data-k=\"comment\">// readonly borrowed access</span></span></span><span class=\"markdown-code-line\"><span class=\"markdown-code-gutter\">3</span><span class=\"markdown-code-text\"><span data-k=\"function\">process</span><span data-k=\"punct\">(</span><span data-k=\"punct\">&amp;</span><span data-k=\"name\">user</span><span data-k=\"punct\">)</span><span data-k=\"punct\">;</span>           <span data-k=\"comment\">// mutable borrowed access</span></span></span><span class=\"markdown-code-line\"><span class=\"markdown-code-gutter\">4</span><span class=\"markdown-code-text\"><span data-k=\"function\">process</span><span data-k=\"punct\">(</span><span data-k=\"punct\">&amp;</span>exclusive <span data-k=\"name\">user</span><span data-k=\"punct\">)</span><span data-k=\"punct\">;</span> <span data-k=\"comment\">// exclusive borrowed access</span></span></span><span class=\"markdown-code-line\"><span class=\"markdown-code-gutter\">5</span><span class=\"markdown-code-text\"><span data-k=\"function\">process</span><span data-k=\"punct\">(</span><span data-k=\"punct\">^</span><span data-k=\"name\">user</span><span data-k=\"punct\">)</span><span data-k=\"punct\">;</span>           <span data-k=\"comment\">// owned value</span></span></span></code></pre></figure><p>Dispatch resolution uses the actual form during overload resolution, so container interfaces like <code>Iterable&lt;T&gt;</code> can support ordinary TypeScript iteration and borrowed iteration without adding Rust-style method family explosion:</p>\n<figure class=\"markdown-code\"><figcaption><span class=\"markdown-code__title\">Polymorphism</span><span class=\"markdown-code__format\">.ds</span></figcaption><pre tabindex=\"0\"><code class=\"markdown-code-lines\"><span class=\"markdown-code-line\"><span class=\"markdown-code-gutter\">1</span><span class=\"markdown-code-text\"><span data-k=\"keyword\">declare</span> <span data-k=\"keyword\">type</span> <span data-k=\"type\">Point</span> <span data-k=\"punct\">=</span> <span data-k=\"punct\">{</span> <span data-k=\"property\">x</span><span data-k=\"punct\">:</span> <span data-k=\"type\">number</span><span data-k=\"punct\">;</span> <span data-k=\"property\">y</span><span data-k=\"punct\">:</span> <span data-k=\"type\">number</span> <span data-k=\"punct\">}</span><span data-k=\"punct\">;</span></span></span><span class=\"markdown-code-line\"><span class=\"markdown-code-gutter\">2</span><span class=\"markdown-code-text\"><span data-k=\"keyword\">declare</span> <span data-k=\"keyword\">const</span> <span data-k=\"name\">points</span><span data-k=\"punct\">:</span> <span data-k=\"type\">Array</span><span data-k=\"punct\">&lt;</span><span data-k=\"type\">Point</span><span data-k=\"punct\">&gt;</span><span data-k=\"punct\">;</span></span></span><span class=\"markdown-code-line\"><span class=\"markdown-code-gutter\">3</span><span class=\"markdown-code-text\"> </span></span><span class=\"markdown-code-line\"><span class=\"markdown-code-gutter\">4</span><span class=\"markdown-code-text\"><span data-k=\"comment\">// ordinary &quot;managed&quot; iteration</span></span></span><span class=\"markdown-code-line\"><span class=\"markdown-code-gutter\">5</span><span class=\"markdown-code-text\"><span data-k=\"keyword\">for</span> <span data-k=\"punct\">(</span><span data-k=\"keyword\">const</span> <span data-k=\"name\">point</span> <span data-k=\"keyword\">of</span> <span data-k=\"name\">points</span><span data-k=\"punct\">)</span> <span data-k=\"punct\">{</span></span></span><span class=\"markdown-code-line\"><span class=\"markdown-code-gutter\">6</span><span class=\"markdown-code-text\">    <span data-k=\"name\">point</span> <span data-k=\"keyword\">satisfies</span> <span data-k=\"type\">Point</span><span data-k=\"punct\">;</span></span></span><span class=\"markdown-code-line\"><span class=\"markdown-code-gutter\">7</span><span class=\"markdown-code-text\"><span data-k=\"punct\">}</span></span></span><span class=\"markdown-code-line\"><span class=\"markdown-code-gutter\">8</span><span class=\"markdown-code-text\"> </span></span><span class=\"markdown-code-line\"><span class=\"markdown-code-gutter\">9</span><span class=\"markdown-code-text\"><span data-k=\"comment\">// readonly borrowed iteration</span></span></span><span class=\"markdown-code-line\"><span class=\"markdown-code-gutter\">10</span><span class=\"markdown-code-text\"><span data-k=\"keyword\">for</span> <span data-k=\"punct\">(</span><span data-k=\"keyword\">const</span> <span data-k=\"name\">point</span> <span data-k=\"keyword\">of</span> <span data-k=\"punct\">&amp;</span><span data-k=\"keyword\">readonly</span> <span data-k=\"name\">points</span><span data-k=\"punct\">)</span> <span data-k=\"punct\">{</span></span></span><span class=\"markdown-code-line\"><span class=\"markdown-code-gutter\">11</span><span class=\"markdown-code-text\">    <span data-k=\"name\">point</span> <span data-k=\"keyword\">satisfies</span> <span data-k=\"punct\">&amp;</span><span data-k=\"keyword\">readonly</span> <span data-k=\"type\">Point</span><span data-k=\"punct\">;</span></span></span><span class=\"markdown-code-line\"><span class=\"markdown-code-gutter\">12</span><span class=\"markdown-code-text\"><span data-k=\"punct\">}</span></span></span><span class=\"markdown-code-line\"><span class=\"markdown-code-gutter\">13</span><span class=\"markdown-code-text\"> </span></span><span class=\"markdown-code-line\"><span class=\"markdown-code-gutter\">14</span><span class=\"markdown-code-text\"><span data-k=\"comment\">// mutable borrowed iteration</span></span></span><span class=\"markdown-code-line\"><span class=\"markdown-code-gutter\">15</span><span class=\"markdown-code-text\"><span data-k=\"keyword\">for</span> <span data-k=\"punct\">(</span><span data-k=\"keyword\">const</span> <span data-k=\"name\">point</span> <span data-k=\"keyword\">of</span> <span data-k=\"punct\">&amp;</span><span data-k=\"name\">points</span><span data-k=\"punct\">)</span> <span data-k=\"punct\">{</span></span></span><span class=\"markdown-code-line\"><span class=\"markdown-code-gutter\">16</span><span class=\"markdown-code-text\">    <span data-k=\"name\">point</span> <span data-k=\"keyword\">satisfies</span> <span data-k=\"punct\">&amp;</span><span data-k=\"type\">Point</span><span data-k=\"punct\">;</span></span></span><span class=\"markdown-code-line\"><span class=\"markdown-code-gutter\">17</span><span class=\"markdown-code-text\"><span data-k=\"punct\">}</span></span></span><span class=\"markdown-code-line\"><span class=\"markdown-code-gutter\">18</span><span class=\"markdown-code-text\"> </span></span><span class=\"markdown-code-line\"><span class=\"markdown-code-gutter\">19</span><span class=\"markdown-code-text\"><span data-k=\"comment\">// exclusive borrowed iteration</span></span></span><span class=\"markdown-code-line\"><span class=\"markdown-code-gutter\">20</span><span class=\"markdown-code-text\"><span data-k=\"keyword\">for</span> <span data-k=\"punct\">(</span><span data-k=\"keyword\">const</span> <span data-k=\"name\">point</span> <span data-k=\"keyword\">of</span> <span data-k=\"punct\">&amp;</span>exclusive <span data-k=\"name\">points</span><span data-k=\"punct\">)</span> <span data-k=\"punct\">{</span></span></span><span class=\"markdown-code-line\"><span class=\"markdown-code-gutter\">21</span><span class=\"markdown-code-text\">    <span data-k=\"name\">point</span> <span data-k=\"keyword\">satisfies</span> <span data-k=\"punct\">&amp;</span>exclusive <span data-k=\"type\">Point</span><span data-k=\"punct\">;</span></span></span><span class=\"markdown-code-line\"><span class=\"markdown-code-gutter\">22</span><span class=\"markdown-code-text\"><span data-k=\"punct\">}</span></span></span><span class=\"markdown-code-line\"><span class=\"markdown-code-gutter\">23</span><span class=\"markdown-code-text\"> </span></span><span class=\"markdown-code-line\"><span class=\"markdown-code-gutter\">24</span><span class=\"markdown-code-text\"><span data-k=\"comment\">// moved iteration</span></span></span><span class=\"markdown-code-line\"><span class=\"markdown-code-gutter\">25</span><span class=\"markdown-code-text\"><span data-k=\"keyword\">for</span> <span data-k=\"punct\">(</span><span data-k=\"keyword\">const</span> <span data-k=\"name\">point</span> <span data-k=\"keyword\">of</span> <span data-k=\"punct\">^</span><span data-k=\"name\">points</span><span data-k=\"punct\">)</span> <span data-k=\"punct\">{</span></span></span><span class=\"markdown-code-line\"><span class=\"markdown-code-gutter\">26</span><span class=\"markdown-code-text\">    <span data-k=\"name\">point</span> <span data-k=\"keyword\">satisfies</span> <span data-k=\"type\">Point</span><span data-k=\"punct\">;</span></span></span><span class=\"markdown-code-line\"><span class=\"markdown-code-gutter\">27</span><span class=\"markdown-code-text\"><span data-k=\"punct\">}</span></span></span></code></pre></figure><h2 id=\"capabilities\">Capabilities</h2><p>Inspired by many other systems-y languages, Destack encodes synchronization and memory primitives as trait-like interfaces like <code>Copy</code>, <code>Clone</code>, <code>Send</code>, and <code>Sync</code>.</p>\n<div class=\"markdown-table\" tabindex=\"0\"><table><thead><tr>\n<th>Capability</th>\n<th>Meaning</th>\n</tr>\n</thead><tbody><tr>\n<td><code>Copy</code></td>\n<td>Value can be duplicated implicitly without changing ownership responsibilities.</td>\n</tr>\n<tr>\n<td><code>Clone</code></td>\n<td>Code can explicitly create another value, possibly by running code or allocating.</td>\n</tr>\n<tr>\n<td><code>Send</code></td>\n<td>Value can cross a Worker boundary.</td>\n</tr>\n<tr>\n<td><code>Sync</code></td>\n<td>References to shared values can be used concurrently through the type&#39;s own API.</td>\n</tr>\n</tbody></table></div><p>Like Rust&#39;s auto traits, <code>Send</code> and <code>Sync</code> are derived structurally by default (a type is <code>Send</code> when all of its fields are) and can be opted out of explicitly.\nImplementing <code>Send</code> or <code>Sync</code> <em>manually</em> - against the structural evidence, as interior-mutability primitives must - is an <code>@unsafe</code> claim like any other unchecked memory assertion.\nFor borrows and handles, the rules follow per memory form:</p>\n<div class=\"markdown-table\" tabindex=\"0\"><table><thead><tr>\n<th>Form</th>\n<th>Crosses Workers when</th>\n</tr>\n</thead><tbody><tr>\n<td><code>T</code> (local managed)</td>\n<td>never, local handles stay on their Worker</td>\n</tr>\n<tr>\n<td><code>shared T</code></td>\n<td><code>T: Sync</code> for aliased access</td>\n</tr>\n<tr>\n<td><code>^T</code></td>\n<td><code>T: Send</code></td>\n</tr>\n<tr>\n<td><code>&amp;readonly T</code></td>\n<td><code>T: Sync</code>, and the source is owned or static</td>\n</tr>\n<tr>\n<td><code>&amp;exclusive T</code></td>\n<td><code>T: Send</code>, and the source is owned or static</td>\n</tr>\n<tr>\n<td><code>&amp;T</code></td>\n<td>never, aliased mutability</td>\n</tr>\n<tr>\n<td><code>shared</code> static binding</td>\n<td>requires <code>T: Sync</code> outright, the binding reaches every Worker by construction</td>\n</tr>\n</tbody></table></div><p>The <code>&amp;T</code> row is the important one: the aliased-mutable middle of the borrow ladder is only safe because a Worker is a single-threaded execution domain, and so it must never cross a Worker boundary.\nAlso, note again <code>shared T</code> means <code>T</code> lives in <a href=\"#shared-space\">shared space</a>; it does <em>not</em> make <code>T</code> automatically <code>Sync</code> by itself.\nUserland APIs such as channels, Worker pools, atomics, locks, and actors can require <code>Send</code> or <code>Sync</code> when they need those stronger guarantees, very similar to Rust or even Swift.</p>\n<h2 id=\"synchronization\">Synchronization</h2><p>The standard library provides the usual memory and synchronization primitives on top of this unified memory system.\nThe full details are documented in the library, but the basics should be familiar to anyone with a systems-level background.\nThis is also where the <code>@unsafe</code> actually lives: a <code>Mutex&lt;T&gt;</code> mutates through a non-exclusive receiver via <code>UnsafeCell</code> and atomics, and its guard manufactures the <code>&amp;exclusive T</code> that the runtime lock (not the borrow checker) guarantees - userland just composes the safe surface.</p>\n<div class=\"markdown-table\" tabindex=\"0\"><table><thead><tr>\n<th>Primitive</th>\n<th>Contract</th>\n</tr>\n</thead><tbody><tr>\n<td><code>Box&lt;T&gt;</code></td>\n<td>unique heap ownership for <code>Owned&lt;T&gt;</code>, with deterministic drop when <code>T: Drop</code></td>\n</tr>\n<tr>\n<td><code>Rc&lt;T&gt;</code></td>\n<td>local shared ownership of <code>Owned&lt;T&gt;</code>, non-atomic refcount, not transferable across Workers</td>\n</tr>\n<tr>\n<td><code>Arc&lt;T&gt;</code></td>\n<td>shared ownership of <code>Owned&lt;T&gt;</code>, atomic refcount, transferable when <code>T</code> satisfies the required <code>Send</code> / <code>Sync</code> bounds</td>\n</tr>\n<tr>\n<td><code>Cell&lt;T&gt;</code></td>\n<td>local interior mutation by value, for small <code>Copy</code>-like state</td>\n</tr>\n<tr>\n<td><code>RefCell&lt;T&gt;</code></td>\n<td>local runtime borrow checking for cases static borrowing cannot express cleanly</td>\n</tr>\n<tr>\n<td><code>Atomic&lt;T&gt;</code></td>\n<td>lock-free scalar storage with explicit ordering and scope</td>\n</tr>\n<tr>\n<td><code>AsyncMutex&lt;T&gt;</code></td>\n<td>local mutual exclusion that suspends the current async task, not the Worker</td>\n</tr>\n<tr>\n<td><code>Mutex&lt;T&gt;</code></td>\n<td>shared mutual exclusion backed by atomics and runtime wait/wake support</td>\n</tr>\n</tbody></table></div><p>Because ownership and placement are part of our type system, and we can query and gate based on contextual type information using regular TypeScript algebra, we have a lot of flexibility and gain some nice ergonomics.\nFor example, we can provide ergonomic context-aware aliases that conform to the way they are used:</p>\n<figure class=\"markdown-code\"><figcaption><span class=\"markdown-code__title\">Synchronization</span><span class=\"markdown-code__format\">.ds</span></figcaption><pre tabindex=\"0\"><code class=\"markdown-code-lines\"><span class=\"markdown-code-line\"><span class=\"markdown-code-gutter\">1</span><span class=\"markdown-code-text\"><span data-k=\"keyword\">type</span> <span data-k=\"type\">Ref</span><span data-k=\"punct\">&lt;</span><span data-k=\"type\">T</span><span data-k=\"punct\">&gt;</span> <span data-k=\"punct\">=</span></span></span><span class=\"markdown-code-line\"><span class=\"markdown-code-gutter\">2</span><span class=\"markdown-code-text\">    <span data-k=\"type\">PlaceIn</span><span data-k=\"punct\">&lt;</span><span data-k=\"type\">T</span><span data-k=\"punct\">,</span> <span data-k=\"string\">&quot;local&quot;</span><span data-k=\"punct\">&gt;</span> <span data-k=\"keyword\">extends</span> <span data-k=\"string\">&quot;shared&quot;</span> <span data-k=\"punct\">?</span> <span data-k=\"type\">Arc</span><span data-k=\"punct\">&lt;</span><span data-k=\"type\">T</span><span data-k=\"punct\">&gt;</span> <span data-k=\"punct\">:</span> <span data-k=\"type\">Rc</span><span data-k=\"punct\">&lt;</span><span data-k=\"type\">T</span><span data-k=\"punct\">&gt;</span><span data-k=\"punct\">;</span></span></span><span class=\"markdown-code-line\"><span class=\"markdown-code-gutter\">3</span><span class=\"markdown-code-text\"> </span></span><span class=\"markdown-code-line\"><span class=\"markdown-code-gutter\">4</span><span class=\"markdown-code-text\"><span data-k=\"keyword\">type</span> <span data-k=\"type\">Lock</span><span data-k=\"punct\">&lt;</span><span data-k=\"type\">T</span><span data-k=\"punct\">&gt;</span> <span data-k=\"punct\">=</span></span></span><span class=\"markdown-code-line\"><span class=\"markdown-code-gutter\">5</span><span class=\"markdown-code-text\">    <span data-k=\"type\">PlaceIn</span><span data-k=\"punct\">&lt;</span><span data-k=\"type\">T</span><span data-k=\"punct\">,</span> <span data-k=\"string\">&quot;local&quot;</span><span data-k=\"punct\">&gt;</span> <span data-k=\"keyword\">extends</span> <span data-k=\"string\">&quot;shared&quot;</span> <span data-k=\"punct\">?</span> <span data-k=\"type\">Mutex</span><span data-k=\"punct\">&lt;</span><span data-k=\"type\">T</span><span data-k=\"punct\">&gt;</span> <span data-k=\"punct\">:</span> <span data-k=\"type\">AsyncMutex</span><span data-k=\"punct\">&lt;</span><span data-k=\"type\">T</span><span data-k=\"punct\">&gt;</span><span data-k=\"punct\">;</span></span></span></code></pre></figure>", {  }),
} satisfies DocumentContent;

export default content;

/// Replace build-time asset placeholders with bundled URLs.
function resolveAssets(html: string, assets: Record<string, string>) {
    let resolved = html;

    for (const [placeholder, asset] of Object.entries(assets)) {
        resolved = resolved.replaceAll(placeholder, asset);
    }

    return resolved;
}
